   "code": "from build123d import *\nfrom math import pi, cos, sin\n\n# Dimensions\nouter_diameter = 120\nbore_diameter = 40\nthickness = 14\nbolt_hole_diameter = 11\nbolt_circle_diameter = 95\n\n# 1. Create main flange cylinder\nmain_flange = Cylinder(\n    radius=outer_diameter/2,\n    height=thickness,\n    align=(Align.CENTER, Align.CENTER, Align.MIN)\n)\n\n# 2. Create through bore and subtract\nbore = Cylinder(\n    radius=bore_diameter/2,\n    height=thickness,\n    align=(Align.CENTER, Align.CENTER, Align.MIN)\n)\nflange_with_bore = main_flange - bore\n\n# 3. Create first bolt hole at angle 0\u00b0 (X-axis)\nbolt_hole_radius = bolt_hole_diameter/2\npcd_radius = bolt_circle_diameter/2\nfirst_bolt_hole = Cylinder(\n    radius=bolt_hole_radius,\n    height=thickness,\n    align=(Align.CENTER, Align.CENTER, Align.MIN)\n)\nfirst_bolt_hole = Pos(pcd_radius, 0, 0) * first_bolt_hole\n\n# 4. Create bolt hole pattern (six holes at 60\u00b0 intervals)\nbolt_holes = [first_bolt_hole]\nfor i in range(1, 6):\n    angle = i * 60\n    bolt_hole = Cylinder(\n        radius=bolt_hole_radius,\n        height=thickness,\n        align=(Align.CENTER, Align.CENTER, Align.MIN)\n    )\n    x = pcd_radius * cos(angle * pi/180)\n    y = pcd_radius * sin(angle * pi/180)\n    bolt_hole = Pos(x, y, 0) * bolt_hole\n    bolt_holes.append(bolt_hole)\n\n# 5. Subtract all bolt holes from flange\nresult = flange_with_bore\nfor bolt_hole in bolt_holes:\n    result -= bolt_hole",
