   "code": "import build123d as bd\n\n# Define the dimensions\nplate_length = 80.0  # mm\nplate_width = 80.0   # mm (square plate, so length = width)\nplate_thickness = 8.0  # mm\nhole_diameter = 9.0   # mm\nhole_offset = 25.0    # mm (distance from plate center to hole center)\nhole_pattern_spacing = 50.0  # mm (center-to-center spacing between holes)\n\n# 1. Create base rectangular plate\nwith bd.BuildPart() as plate_builder:\n    bd.Box(plate_length, plate_width, plate_thickness)\n\n# Extract the base plate solid\nbase_plate = plate_builder.part\n\n# 2. Define top face as primary planar datum (for reference)\n# We'll use the top face (facing +Z) for positioning if needed\ntop_face = base_plate.faces().sort_by(bd.Axis.Z)[-1]\n\n# 3. Define vertical central axis as primary axial datum (for reference)\nvertical_axis = bd.Axis.Z\n\n# 4. Create first fastener hole in first quadrant\nwith bd.BuildPart() as hole_builder:\n    # Position the hole in the first quadrant (X+, Y+)\n    hole_location = bd.Location((hole_offset, hole_offset, 0))\n    bd.Cylinder(radius=hole_diameter/2, height=plate_thickness, \n                align=(bd.Align.CENTER, bd.Align.CENTER, bd.Align.CENTER))\n    hole_builder.part.location = hole_location\n\n# Extract the first hole\nfirst_hole = hole_builder.part\n\n# Create the plate with holes by subtracting from base plate\nwith bd.BuildPart() as final_builder:\n    # Add the base plate\n    bd.add(base_plate)\n    \n    # Subtract the first hole\n    bd.subtract(first_hole)\n    \n    # 5. Pattern to other quadrants using mirror operations\n    # Mirror across YZ plane (X=0) to get second quadrant (X-, Y+)\n    hole_mirror_x = first_hole.mirror(bd.Plane.YZ)\n    bd.subtract(hole_mirror_x)\n    \n    # Mirror across XZ plane (Y=0) to get fourth quadrant (X+, Y-)\n    hole_mirror_y = first_hole.mirror(bd.Plane.XZ)\n    bd.subtract(hole_mirror_y)\n    \n    # Mirror across both planes to get third quadrant (X-, Y-)\n    hole_mirror_xy = first_hole.mirror(bd.Plane.YZ).mirror(bd.Plane.XZ)\n    bd.subtract(hole_mirror_xy)\n\n# Assign the final solid\nresult = final_builder.part",
