   "code": "from build123d import *\n\n# Create a circular pipe flange with the following specifications:\n# - Outer diameter: 120 mm\n# - Through bore: 40 mm diameter\n# - Six bolt holes: 11 mm diameter on 95 mm PCD\n# - Thickness: 14 mm\n\n# Start with the main cylindrical body\nflange_od = 120\nflange_thickness = 14\nbore_diameter = 40\nbolt_hole_diameter = 11\nbolt_pcd = 95\nnum_bolts = 6\n\n# Create the main flange plate\nflange_body = Cylinder(radius=flange_od/2, height=flange_thickness)\n\n# Create the central bore (through hole)\ncentral_bore = Cylinder(radius=bore_diameter/2, height=flange_thickness)\n\n# Create the six bolt holes\nbolt_holes = []\nfor i in range(num_bolts):\n    angle = (360 / num_bolts) * i\n    # Position on the PCD\n    x = (bolt_pcd / 2) * cos(angle * pi / 180)\n    y = (bolt_pcd / 2) * sin(angle * pi / 180)\n    # Create the bolt hole at this location\n    bolt_hole = Cylinder(\n        radius=bolt_hole_diameter/2,\n        height=flange_thickness,\n        align=(Align.CENTER, Align.CENTER, Align.MIN)\n    )\n    bolt_hole = bolt_hole.translate((x, y, 0))\n    bolt_holes.append(bolt_hole)\n\n# Combine all holes\nall_holes = central_bore\nfor hole in bolt_holes:\n    all_holes = all_holes | hole\n\n# Subtract all holes from the flange body\nresult = flange_body - all_holes",
