   "code": "from build123d import *\nimport math\n\n# Define dimensions\nouter_diameter = 120\ncenter_bore_diameter = 40\nbolt_count = 6\nbolt_hole_diameter = 11\nbolt_pcd = 95\nplate_thickness = 14\n\n# Create the base plate cylinder\nbase_plate = Cylinder(radius=outer_diameter/2, height=plate_thickness)\n\n# Create the center bore (concentric through-hole)\ncenter_bore = Cylinder(radius=center_bore_diameter/2, height=plate_thickness)\n\n# Subtract the center bore from the base plate\nresult = base_plate - center_bore\n\n# Create and subtract the six bolt holes\n# Six holes equally spaced at 60\u00b0 intervals on the PCD\nfor i in range(bolt_count):\n    angle_rad = (i * 360 / bolt_count) * math.pi / 180\n    \n    # Position of bolt hole center on the PCD\n    x_pos = (bolt_pcd / 2) * math.cos(angle_rad)\n    y_pos = (bolt_pcd / 2) * math.sin(angle_rad)\n    \n    # Create bolt hole cylinder at this position\n    bolt_hole = Cylinder(\n        radius=bolt_hole_diameter/2,\n        height=plate_thickness\n    ).translate((x_pos, y_pos, 0))\n    \n    # Subtract from result\n    result = result - bolt_hole\n\nDIMS: {\"bolt_count\": 6, \"bolt_hole_diameter\": 11, \"bolt_pcd\": 95, \"center_bore_diameter\": 40, \"outer_diameter\": 120, \"plate_thickness\": 14}",
