   "code": "from build123d import *\n\n# Define dimensions\nod = 120  # Outer diameter mm\nbore_id = 40  # Central bore diameter mm\nbolt_hole_dia = 11  # Bolt hole diameter mm\nbolt_pcd = 95  # Bolt circle diameter (PCD) mm\nnum_bolts = 6  # Number of bolts\nthickness = 14  # Plate thickness mm\n\n# Create base plate\nbase_sketch = Sketch()\nbase_sketch.circle(od / 2)\nbase_plate = pad(base_sketch, thickness)\n\n# Create central bore on top face\ntop_face = base_plate.faces().sort_by(Axis.Z)[-1]\nbore_sketch = Sketch(top_face)\nbore_sketch.circle(bore_id / 2)\nflange_with_bore = pocket(base_plate, bore_sketch, depth=thickness)\n\n# Create bolt hole pattern\nbolt_holes_sketch = Sketch(top_face)\n\n# Calculate bolt hole positions (6 equally spaced at 60\u00b0 intervals)\nbolt_radius = bolt_pcd / 2\nfor i in range(num_bolts):\n    angle = i * (360 / num_bolts)  # 0\u00b0, 60\u00b0, 120\u00b0, 180\u00b0, 240\u00b0, 300\u00b0\n    import math\n    x = bolt_radius * math.cos(math.radians(angle))\n    y = bolt_radius * math.sin(math.radians(angle))\n    bolt_holes_sketch.push(Point(x, y))\n    bolt_holes_sketch.circle(bolt_hole_dia / 2)\n\n# Pocket the bolt holes through the entire thickness\nresult = pocket(flange_with_bore, bolt_holes_sketch, depth=thickness)",
