   "code": "from build123d import *\n\n# Dimension definitions\nplate_length = 80  # mm\nplate_width = 80  # mm\nplate_thickness = 8  # mm\nhole_diameter = 9  # mm\npattern_size = 50  # mm (50x50 square pattern)\nhole_offset_x = 25  # mm from center\nhole_offset_y = 25  # mm from center\n\n# Create the base plate\nplate = Box(plate_length, plate_width, plate_thickness, align=(Align.CENTER, Align.CENTER, Align.MIN))\n\n# Create holes at the four corner positions of the 50x50 pattern\n# Hole positions relative to center: (\u00b125, \u00b125)\nhole_positions = [\n    (hole_offset_x, hole_offset_y),\n    (hole_offset_x, -hole_offset_y),\n    (-hole_offset_x, hole_offset_y),\n    (-hole_offset_x, -hole_offset_y),\n]\n\n# Create cylinders for each hole\nhole_radius = hole_diameter / 2\nresult = plate\n\nfor x, y in hole_positions:\n    # Create a cylinder positioned at (x, y) that goes through the full thickness\n    hole = Cylinder(\n        radius=hole_radius,\n        height=plate_thickness * 2,  # Make it taller to ensure complete penetration\n        align=(Align.CENTER, Align.CENTER, Align.MIN)\n    )\n    # Position the hole at the correct location\n    hole = hole.translate((x, y, -plate_thickness / 2))\n    result = result - hole",
