   "code": "from build123d import *\n\n# Create a plain flat washer\n# Outside diameter: 40 mm, Inside diameter: 21 mm, Thickness: 3 mm\n\n# Define dimensions\noutside_diameter = 40\ninside_diameter = 21\nthickness = 3\n\noutside_radius = outside_diameter / 2\ninside_radius = inside_diameter / 2\n\n# Create sketch on XY plane\nwith BuildSketch() as sketch:\n    # Draw outer circle\n    Circle(outside_radius)\n    # Draw inner circle (hole) - will be subtracted\n    Circle(inside_radius)\n\n# Extrude the sketch to create the washer\n# The outer circle creates the solid, inner circle creates the hole\nresult = extrude(sketch.sketch, amount=thickness, dir=(0, 0, 1))",
