   "code": "from build123d import *\n\n# Create a stepped cylindrical shaft with the following specifications:\n# - Total length: 120 mm\n# - Central section: 40 mm diameter, 80 mm long\n# - Two bearing seats at each end: 30 mm diameter, 20 mm long each\n\n# Calculate positions\n# Central section is 80 mm long, positioned in the middle\n# Total length is 120 mm, so we have (120 - 80) / 2 = 20 mm on each end for bearing seats\n\ncentral_length = 80\ncentral_diameter = 40\nbearing_diameter = 30\nbearing_length = 20\ntotal_length = 120\n\n# Verify: bearing_length + central_length + bearing_length = 20 + 80 + 20 = 120 \u2713\n\n# Create the shaft by combining cylinders\n# First bearing seat (left)\nbearing_left = Cylinder(bearing_diameter / 2, bearing_length)\n\n# Central section\ncentral = Cylinder(central_diameter / 2, central_length)\n\n# Second bearing seat (right)\nbearing_right = Cylinder(bearing_diameter / 2, bearing_length)\n\n# Position the sections along the z-axis\n# bearing_left: from z=0 to z=20\n# central: from z=20 to z=100\n# bearing_right: from z=100 to z=120\n\nbearing_left_positioned = bearing_left.translate((0, 0, bearing_length / 2))\ncentral_positioned = central.translate((0, 0, bearing_length + central_length / 2))\nbearing_right_positioned = bearing_right.translate((0, 0, bearing_length + central_length + bearing_length / 2))\n\n# Combine all sections\nresult = bearing_left_positioned + central_positioned + bearing_right_positioned",
