   "code": "from build123d import *\nimport math\n\n# Flange parameters (mm)\nOD = 120.0          # outer diameter\nbore_d = 40.0       # through bore diameter\nbolt_d = 11.0       # bolt hole diameter\nPCD = 95.0          # bolt pitch circle diameter\nthickness = 14.0    # plate thickness\nnum_bolts = 6       # number of bolt holes\n\n# Base flange disk\nflange = Cylinder(radius=OD / 2, height=thickness)\n\n# Concentric through bore\nflange -= Cylinder(radius=bore_d / 2, height=thickness)\n\n# Six equally-spaced bolt holes on the PCD\nfor i in range(num_bolts):\n    angle = i * 2 * math.pi / num_bolts\n    x = (PCD / 2) * math.cos(angle)\n    y = (PCD / 2) * math.sin(angle)\n    flange -= Pos(x, y, 0) * Cylinder(radius=bolt_d / 2, height=thickness)\n\nresult = flange",
