   "code": "from build123d import *\nimport math\n\n# Parameters (mm)\nouter_diameter = 120.0\nbore_diameter = 40.0\nthickness = 14.0\nbolt_hole_diameter = 11.0\npcd = 95.0\nnum_bolts = 6\n\n# Derived radii\nouter_radius = outer_diameter / 2.0\nbore_radius = bore_diameter / 2.0\nbolt_radius = bolt_hole_diameter / 2.0\npcd_radius = pcd / 2.0\n\n# Base plate: cylinder centred in XY, bottom face at Z=0\nflange = Cylinder(\n    radius=outer_radius,\n    height=thickness,\n    align=(Align.CENTER, Align.CENTER, Align.MIN),\n)\n\n# Central bore \u2014 through-cut (slightly over-height to guarantee full penetration)\nbore = Cylinder(\n    radius=bore_radius,\n    height=thickness + 2,\n    align=(Align.CENTER, Align.CENTER, Align.MIN),\n)\nbore = Pos(0, 0, -1) * bore\nflange -= bore\n\n# Six bolt holes on PCD, equally spaced at 60\u00b0 intervals\nfor i in range(num_bolts):\n    angle = math.radians(i * 360.0 / num_bolts)\n    x = pcd_radius * math.cos(angle)\n    y = pcd_radius * math.sin(angle)\n    hole = Cylinder(\n        radius=bolt_radius,\n        height=thickness + 2,\n        align=(Align.CENTER, Align.CENTER, Align.MIN),\n    )\n    hole = Pos(x, y, -1) * hole\n    flange -= hole\n\nresult = flange",
