   "code": "from build123d import *\n\nouter_diameter = 120.0\nbore_diameter = 40.0\nthickness = 14.0\npcd = 95.0\nnum_bolts = 6\nbolt_hole_diameter = 11.0\n\nwith BuildPart() as bp:\n    # Base disk centered at origin\n    Cylinder(\n        radius=outer_diameter / 2,\n        height=thickness,\n        align=(Align.CENTER, Align.CENTER, Align.CENTER),\n    )\n    # Central through bore\n    Cylinder(\n        radius=bore_diameter / 2,\n        height=thickness + 2,\n        align=(Align.CENTER, Align.CENTER, Align.CENTER),\n        mode=Mode.SUBTRACT,\n    )\n    # Six bolt holes on PCD, drilled from top face\n    with Locations(bp.faces().sort_by(Axis.Z)[-1]):\n        with PolarLocations(radius=pcd / 2, count=num_bolts):\n            Hole(radius=bolt_hole_diameter / 2, depth=thickness + 1)\n\nresult = bp.part",
