   "code": "from build123d import *\n\n# Parameters\nouter_diameter = 120.0\nbore_diameter = 40.0\nbolt_circle_diameter = 95.0\nbolt_hole_diameter = 11.0\nthickness = 14.0\nnum_bolt_holes = 6\n\n# Base solid: circular plate\nflange = Cylinder(\n    radius=outer_diameter / 2,\n    height=thickness,\n    align=(Align.CENTER, Align.CENTER, Align.MIN),\n)\n\n# Central bore\nflange -= Cylinder(\n    radius=bore_diameter / 2,\n    height=thickness,\n    align=(Align.CENTER, Align.CENTER, Align.MIN),\n)\n\n# Bolt holes: 6 equally spaced on the bolt circle\nbolt_radius = bolt_circle_diameter / 2\nfor i in range(num_bolt_holes):\n    angle = i * (360 / num_bolt_holes)\n    hole = Cylinder(\n        radius=bolt_hole_diameter / 2,\n        height=thickness,\n        align=(Align.CENTER, Align.CENTER, Align.MIN),\n    )\n    hole = hole.moved(Location((bolt_radius, 0, 0)))\n    hole = hole.moved(Rotation(0, 0, angle))\n    flange -= hole\n\nresult = flange",
