   "code": "from build123d import *\n\n# Wall plate: 60 mm (X) x 8 mm (Y) x 40 mm (Z)\n# Positioned from (0, 0, 0) to (60, 8, 40), center at (30, 4, 20)\nwall = Pos(30, 4, 20) * Box(60, 8, 40)\n\n# Base plate: 60 mm (X) x 40 mm (Y) x 8 mm (Z)\n# Positioned from (0, 8, 0) to (60, 48, 8), center at (30, 28, 4)\nbase = Pos(30, 28, 4) * Box(60, 40, 8)\n\nbracket = wall + base\n\n# Hole 1: \u00d88 through base plate (vertical Z-axis)\n# Centered at X=30, Y = 8 (wall inner face) + 28 = 36\nhole1 = Pos(30, 36, 4) * Cylinder(radius=4, height=20)\nbracket -= hole1\n\n# Hole 2: \u00d88 through vertical wall (horizontal Y-axis)\n# Centered at X=30, Z=24 (24 mm above base bottom)\n# Cylinder default axis is Z; rotate 90\u00b0 about X to align with Y\nhole2 = Pos(30, 4, 24) * Rot(90, 0, 0) * Cylinder(radius=4, height=20)\nbracket -= hole2\n\nresult = bracket",
