   "code": "from build123d import *\n\n# \u2500\u2500 Base plate: 60 \u00d7 40 \u00d7 8 mm (horizontal) \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n# Placed so it spans  X \u2208 [-30, 30], Y \u2208 [0, 40], Z \u2208 [0, 8]\nbase = Pos(0, 20, 4) * Box(60, 40, 8)\n\n# \u2500\u2500 Vertical wall: 60 wide \u00d7 8 thick \u00d7 40 tall \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n# Rises from the Y = 0 edge of the base, outer face at Y = -8\n# Spans  X \u2208 [-30, 30], Y \u2208 [-8, 0], Z \u2208 [0, 40]\nwall = Pos(0, -4, 20) * Box(60, 8, 40)\n\n# Combine into a solid L-bracket\nbracket = base + wall\n\n# \u2500\u2500 Hole in base plate \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n# \u00d88 mm (r = 4), vertical axis (Z)\n# Centred 30 mm along width \u2192 X = 0\n# 28 mm from wall inner face (Y = 0) \u2192 Y = 28\nbase_hole = Pos(0, 28, 4) * Cylinder(4, 20)\n\n# \u2500\u2500 Hole in vertical wall \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n# \u00d88 mm (r = 4), horizontal axis (Y)\n# Centred 30 mm along width \u2192 X = 0\n# 24 mm above base bottom (Z = 0) \u2192 Z = 24\n# Rotate cylinder from Z-axis to Y-axis (-90\u00b0 about X)\nwall_hole = Pos(0, -4, 24) * Rot(X=-90) * Cylinder(4, 20)\n\n# \u2500\u2500 Final result \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\nresult = bracket - base_hole - wall_hole",
