   "code": "from build123d import *\n\n# Base plate: 60 mm (X) x 40 mm (Y) x 8 mm (Z), resting on XY plane\nbase = Box(60, 40, 8, align=(Align.MIN, Align.MIN, Align.MIN))\n\n# Vertical wall: 60 mm (X) x 8 mm (Y) x 40 mm (Z)\n# Butts against the Y=0 edge of the base, extending in -Y direction\nwall = Box(60, 8, 40, align=(Align.MIN, Align.MAX, Align.MIN))\n\n# Combine into L-bracket\nbracket = base + wall\n\n# Hole 1: \u00d88 mm vertical through base plate\n# X = 30 mm (centred along 60 mm width)\n# Y = 28 mm (28 mm from wall inner face at Y = 0)\n# Z = 4 mm (mid-thickness of 8 mm base)\nh1 = Cylinder(4, 20).moved(Location((30, 28, 4)))\n\n# Hole 2: \u00d88 mm horizontal through vertical wall (axis along Y)\n# X = 30 mm (centred along 60 mm width)\n# Z = 24 mm (24 mm above base bottom at Z = 0)\n# Y = -4 mm (mid-thickness of 8 mm wall, which spans Y: -8 to 0)\n# Cylinder rotated 90\u00b0 about X so its axis aligns with Y\nh2 = Cylinder(4, 20).moved(Location((30, -4, 24), (90, 0, 0)))\n\nresult = bracket - h1 - h2",
