   "code": "from build123d import *\n\n# Governing dimensions\nbracket_width = 60      # shared width of base and wall\nbase_depth = 40         # depth of base plate (Y direction)\nthickness = 8           # plate thickness\nwall_height = 40        # overall height of wall from base bottom\nhole_dia = 8            # hole diameter\nbase_hole_from_edge = 30   # X position of base hole (centered on width)\nbase_hole_from_wall = 28   # Y distance of base hole from wall inner face\nwall_hole_from_edge = 30   # X position of wall hole (centered on width)\nwall_hole_from_bottom = 24 # Z height of wall hole above base bottom\n\n# Base plate: X 0\u219260, Y 0\u219240, Z 0\u21928\nbase = Box(bracket_width, base_depth, thickness).moved(\n    Location((bracket_width / 2, base_depth / 2, thickness / 2))\n)\n\n# Vertical wall: X 0\u219260, Y -8\u21920, Z 0\u219240\nwall = Box(bracket_width, thickness, wall_height).moved(\n    Location((bracket_width / 2, -thickness / 2, wall_height / 2))\n)\n\n# Fuse into single L-bracket\nbracket = base + wall\n\n# Base hole \u2014 \u00d88 through base plate (vertical Z axis)\n# Centred at X=30, Y=28, Z=4; cylinder height 20 for through-clearance\nbase_hole = Cylinder(hole_dia / 2, 20).moved(\n    Location((base_hole_from_edge, base_hole_from_wall, thickness / 2))\n)\nbracket -= base_hole\n\n# Wall hole \u2014 \u00d88 through wall (horizontal Y axis)\n# Centred at X=30, Y=-4, Z=24; rotate cylinder 90\u00b0 about X so axis aligns with Y\nwall_hole = Cylinder(hole_dia / 2, 20).moved(\n    Location((wall_hole_from_edge, -thickness / 2, wall_hole_from_bottom), (90, 0, 0))\n)\nbracket -= wall_hole\n\nresult = bracket",
   "stl": "models/a201.stl",
   "ref_stl": "models/ref_T2-lbracket.stl"
