   "code": "from build123d import *\n\n# Governing dimensions\nbase_width = 60\nbase_depth = 40\nthickness = 8\noverall_height = 40\nhole_dia = 8\nbase_hole_x = 30\nbase_hole_from_wall = 28\nwall_hole_x = 30\nwall_hole_z = 24\n\n# Base plate: occupies (0,0,0) to (60,40,8)\nbase = Box(base_width, base_depth, thickness, align=(Align.MIN, Align.MIN, Align.MIN))\n\n# Wall plate: occupies (0,32,0) to (60,40,40)\nwall = Pos(0, base_depth - thickness, 0) * Box(\n    base_width, thickness, overall_height,\n    align=(Align.MIN, Align.MIN, Align.MIN),\n)\n\n# Fuse into L-bracket\nlbracket = base + wall\n\n# Base hole \u2014 vertical (Z-axis), centre at x=30, y=40-28=12\nbase_hole_y = base_depth - base_hole_from_wall  # 12\nbase_hole = Pos(base_hole_x, base_hole_y, thickness / 2) * Cylinder(\n    hole_dia / 2, thickness + 2,\n)\n\n# Wall hole \u2014 horizontal (Y-axis), centre at x=30, y=36 (mid-wall), z=24\nwall_hole_y = base_depth - thickness / 2  # 36\nwall_hole = (\n    Pos(wall_hole_x, wall_hole_y, wall_hole_z)\n    * Rot(90, 0, 0)\n    * Cylinder(hole_dia / 2, thickness + 10)\n)\n\n# Subtract holes\nresult = lbracket - base_hole - wall_hole",
