   "code": "from build123d import *\n\n# Governing dimensions\nwall_width = 60\nwall_thickness = 8\nwall_height = 40\nbase_width = 60\nbase_depth = 40\nbase_thickness = 8\nhole_diameter = 8\nbase_hole_x = 30\nbase_hole_from_wall = 28\nwall_hole_x = 30\nwall_hole_height = 24\n\n# --- Step 1: Vertical wall plate ---\n# Box spans X: 0\u219260, Y: 0\u21928, Z: 0\u219240\nwall = Pos(0, 0, 0) * Box(\n    wall_width, wall_thickness, wall_height,\n    align=(Align.MIN, Align.MIN, Align.MIN),\n)\n\n# --- Step 2: Horizontal base plate ---\n# Box spans X: 0\u219260, Y: 8\u219248, Z: 0\u21928\nbase = Pos(0, wall_thickness, 0) * Box(\n    base_width, base_depth, base_thickness,\n    align=(Align.MIN, Align.MIN, Align.MIN),\n)\n\n# --- Step 3: Fuse into single L-bracket ---\nbracket = wall + base\n\n# --- Step 4: Base hole \u00d88, vertical (Z-axis) ---\n# Centred at X=30, Y=8+28=36, through base thickness\nbase_hole = Pos(\n    base_hole_x,\n    wall_thickness + base_hole_from_wall,\n    base_thickness / 2,\n) * Cylinder(\n    hole_diameter / 2,\n    base_thickness + 2,\n    align=(Align.CENTER, Align.CENTER, Align.CENTER),\n)\n\n# --- Step 5: Wall hole \u00d88, horizontal (Y-axis) ---\n# Centred at X=30, Z=24, through wall thickness\n# Create cylinder along Z, rotate 90\u00b0 about X to align axis with Y, then translate\nwall_hole = Pos(\n    wall_hole_x,\n    wall_thickness / 2,\n    wall_hole_height,\n) * Rot(90, 0, 0) * Cylinder(\n    hole_diameter / 2,\n    wall_thickness + 2,\n    align=(Align.CENTER, Align.CENTER, Align.CENTER),\n)\n\n# --- Final result ---\nresult = bracket - base_hole - wall_hole",
