   "code": "from build123d import *\n\n# Parameters\ndisc_radius = 40.0\ndisc_thickness = 16.0\nhub_radius = 16.0\nhub_protrusion = 20.0\nbore_radius = 8.0\noverall_height = 36.0  # disc_thickness + hub_protrusion\n\n# Base disc: cylinder from Z=0 to Z=16\ndisc = Cylinder(\n    radius=disc_radius,\n    height=disc_thickness,\n    align=(Align.CENTER, Align.CENTER, Align.MIN),\n)\n\n# Hub: cylinder from Z=16 to Z=36\nhub = Cylinder(\n    radius=hub_radius,\n    height=hub_protrusion,\n    align=(Align.CENTER, Align.CENTER, Align.MIN),\n)\nhub = Pos(0, 0, disc_thickness) * hub\n\n# Fuse disc and hub\nbody = disc + hub\n\n# Central bore through entire part\nbore = Cylinder(\n    radius=bore_radius,\n    height=overall_height + 2,  # slight overshoot for clean cut\n    align=(Align.CENTER, Align.CENTER, Align.MIN),\n)\nbore = Pos(0, 0, -1) * bore  # offset to ensure through-cut\n\n# Final result\nresult = body - bore",
