   "code": "from build123d import *\n\n# Governing dimensions\ndisc_diameter = 80\ndisc_thickness = 16\nhub_diameter = 32\nhub_height = 20  # overall_height - disc_thickness = 36 - 16\nbore_diameter = 16\noverall_height = 36\n\n# Disc: cylinder from Z=0 to Z=16, centred on origin in XY\ndisc = Pos(0, 0, disc_thickness / 2) * Cylinder(\n    radius=disc_diameter / 2,\n    height=disc_thickness,\n)\n\n# Hub: cylinder from Z=16 to Z=36, coaxial\nhub = Pos(0, 0, disc_thickness + hub_height / 2) * Cylinder(\n    radius=hub_diameter / 2,\n    height=hub_height,\n)\n\n# Combine disc and hub\nblank = disc + hub\n\n# Bore: through-all hole, Z=0 to Z=36\nbore = Pos(0, 0, overall_height / 2) * Cylinder(\n    radius=bore_diameter / 2,\n    height=overall_height,\n)\n\n# Final part\nresult = blank - bore",
