   "code": "from build123d import *\n\n# Governing dimensions\noutside_diameter = 30.0\nbore_diameter = 20.0\nlength = 40.0\nouter_radius = outside_diameter / 2   # 15.0\nbore_radius = bore_diameter / 2        # 10.0\nwall_thickness = (outside_diameter - bore_diameter) / 2  # 5.0\n\n# Build outer cylinder centred at origin (spans Z = -20 to +20)\nouter_cyl = Cylinder(radius=outer_radius, height=length, align=(Align.CENTER, Align.CENTER, Align.CENTER))\n\n# Build bore cylinder (same dimensions, same alignment)\nbore_cyl = Cylinder(radius=bore_radius, height=length, align=(Align.CENTER, Align.CENTER, Align.CENTER))\n\n# Subtract bore from outer to create the bushing sleeve\nresult = outer_cyl - bore_cyl",
