   "code": "from build123d import Cylinder, Align, Mode, BuildPart, Location\n\nOD = 30.0\nID = 20.0\nlength = 40.0\nouter_radius = OD / 2   # 15 mm\ninner_radius = ID / 2   # 10 mm\nwall_thickness = (OD - ID) / 2  # 5 mm\n\nwith BuildPart() as bp:\n    # Outer cylinder, bottom face at Z=0\n    Cylinder(\n        radius=outer_radius,\n        height=length,\n        align=(Align.CENTER, Align.CENTER, Align.MIN),\n    )\n    # Bore cylinder subtracted\n    Cylinder(\n        radius=inner_radius,\n        height=length,\n        align=(Align.CENTER, Align.CENTER, Align.MIN),\n        mode=Mode.SUBTRACT,\n    )\n\nresult = bp.part",
