   "code": "from build123d import *\n\n# Governing dimensions\noutside_diameter = 30  # mm\nbore_diameter = 20     # mm\nlength = 40            # mm\n\noutside_radius = outside_diameter / 2  # 15 mm\nbore_radius = bore_diameter / 2        # 10 mm\nhalf_length = length / 2               # 20 mm\nwall_thickness = (outside_diameter - bore_diameter) / 2  # 5 mm\n\n# Build the bushing\nwith BuildPart() as bushing:\n    # Step 2: Create outer cylinder (symmetric about XY plane)\n    with BuildSketch(Plane.XY) as outer_sketch:\n        Circle(outside_radius)\n    extrude(amount=half_length, both=True)\n\n    # Step 3: Subtract bore cylinder\n    with BuildSketch(Plane.XY) as bore_sketch:\n        Circle(bore_radius)\n    extrude(amount=half_length, both=True, mode=Mode.SUBTRACT)\n\nresult = bushing.part",
