   "code": "from build123d import *\nimport math\n\n# Parameters\nouter_diameter = 120\nbore_diameter = 40\nbolt_hole_diameter = 11\npcd = 95          # Pitch Circle Diameter\nnum_bolts = 6\nthickness = 14\n\nwith BuildPart() as flange:\n    # Main disc\n    Cylinder(radius=outer_diameter / 2, height=thickness)\n    \n    # Central through bore (subtract)\n    Cylinder(radius=bore_diameter / 2, height=thickness, mode=Mode.SUBTRACT)\n    \n    # Six bolt holes equally spaced on PCD\n    pcd_radius = pcd / 2\n    for i in range(num_bolts):\n        angle = math.radians(i * 360 / num_bolts)\n        x = pcd_radius * math.cos(angle)\n        y = pcd_radius * math.sin(angle)\n        with Locations((x, y, 0)):\n            Cylinder(radius=bolt_hole_diameter / 2, height=thickness, mode=Mode.SUBTRACT)\n\nresult = flange.part",
