   "code": "from build123d import *\nimport math\n\n# Parameters\nouter_diameter = 120\nbore_diameter = 40\nbolt_hole_diameter = 11\nbolt_circle_diameter = 95\nplate_thickness = 14\nnum_bolts = 6\n\n# Build the flange\nwith BuildPart() as flange:\n    # Main circular disc\n    with BuildSketch() as sk:\n        Circle(outer_diameter / 2)\n        # Subtract bore\n        Circle(bore_diameter / 2, mode=Mode.SUBTRACT)\n    extrude(amount=plate_thickness)\n    \n    # Add bolt holes\n    with BuildSketch() as bolt_sk:\n        with PolarLocations(bolt_circle_diameter / 2, num_bolts):\n            Circle(bolt_hole_diameter / 2)\n    extrude(amount=plate_thickness, mode=Mode.SUBTRACT)\n\nresult = flange.part",
