   "code": "from build123d import *\nimport math\n\n# Governing dimensions\nouter_diameter = 120\nouter_radius = outer_diameter / 2          # 60\nbore_diameter = 40\nbore_radius = bore_diameter / 2            # 20\nbolt_circle_diameter = 95\nbolt_circle_radius = bolt_circle_diameter / 2  # 47.5\nbolt_hole_diameter = 11\nbolt_hole_count = 6\nbolt_hole_spacing_degrees = 360 / bolt_hole_count  # 60\nplate_thickness = 14\n\n# Step 1: Create base disc\nwith BuildPart() as flange:\n    # Base disc\n    with BuildSketch(Plane.XY) as base_sketch:\n        Circle(outer_radius)\n    extrude(amount=plate_thickness)\n\n    # Step 2: Subtract central bore\n    with BuildSketch(Plane.XY) as bore_sketch:\n        Circle(bore_radius)\n    extrude(amount=plate_thickness, mode=Mode.SUBTRACT)\n\n    # Steps 3 & 4: Subtract 6 bolt holes on PCD\n    with BuildSketch(Plane.XY) as bolt_sketch:\n        for i in range(bolt_hole_count):\n            angle = math.radians(i * bolt_hole_spacing_degrees)\n            x = bolt_circle_radius * math.cos(angle)\n            y = bolt_circle_radius * math.sin(angle)\n            with Locations((x, y)):\n                Circle(bolt_hole_diameter / 2)\n    extrude(amount=plate_thickness, mode=Mode.SUBTRACT)\n\nresult = flange.part",
