   "code": "import math\nfrom build123d import *\n\n# Governing dimensions\nouter_diameter = 120\nbore_diameter = 40\npcd = 95\npcd_radius = pcd / 2  # 47.5 mm\nthickness = 14\nbolt_hole_diameter = 11\nbolt_hole_count = 6\nbolt_hole_spacing_degrees = 360 / bolt_hole_count  # 60 degrees\n\n# Step 1: Create base disc\nbase_disc = Cylinder(radius=outer_diameter / 2, height=thickness, align=(Align.CENTER, Align.CENTER, Align.CENTER))\n\n# Step 2: Cut central bore\nbore = Cylinder(radius=bore_diameter / 2, height=thickness, align=(Align.CENTER, Align.CENTER, Align.CENTER))\nflange = base_disc - bore\n\n# Step 3 & 4: Cut bolt holes at equally spaced positions on PCD\nfor i in range(bolt_hole_count):\n    angle_deg = i * bolt_hole_spacing_degrees\n    angle_rad = math.radians(angle_deg)\n    x = pcd_radius * math.cos(angle_rad)\n    y = pcd_radius * math.sin(angle_rad)\n    bolt_hole = Cylinder(\n        radius=bolt_hole_diameter / 2,\n        height=thickness,\n        align=(Align.CENTER, Align.CENTER, Align.CENTER)\n    ).move(Location((x, y, 0)))\n    flange = flange - bolt_hole\n\nresult = flange",
