   "code": "from build123d import *\nimport math\n\n# Governing dimensions\nouter_diameter = 120\nbore_diameter = 40\nbolt_circle_pcd = 95\nbolt_circle_radius = bolt_circle_pcd / 2  # 47.5\nbolt_hole_diameter = 11\nbolt_hole_count = 6\nbolt_hole_spacing_degrees = 360 / bolt_hole_count  # 60\nthickness = 14\n\n# Step 1: Create base cylinder\nwith BuildPart() as flange:\n    # Base disc\n    with BuildSketch(Plane.XY) as base_sketch:\n        Circle(outer_diameter / 2)\n    extrude(amount=thickness / 2, both=True)\n\n    # Step 2: Cut central bore\n    with BuildSketch(Plane.XY) as bore_sketch:\n        Circle(bore_diameter / 2)\n    extrude(amount=thickness / 2, both=True, mode=Mode.SUBTRACT)\n\n    # Steps 3 & 4: Cut bolt holes in polar pattern\n    with BuildSketch(Plane.XY) as bolt_sketch:\n        for i in range(bolt_hole_count):\n            angle = math.radians(i * bolt_hole_spacing_degrees)\n            cx = bolt_circle_radius * math.cos(angle)\n            cy = bolt_circle_radius * math.sin(angle)\n            with Locations((cx, cy)):\n                Circle(bolt_hole_diameter / 2)\n    extrude(amount=thickness / 2, both=True, mode=Mode.SUBTRACT)\n\nresult = flange.part",
