   "code": "from build123d import *\n\n# Governing dimensions\nplate_length = 80      # mm, X direction\nplate_width = 80       # mm, Y direction\nplate_thickness = 8    # mm, Z direction\nhole_diameter = 9      # mm\nhole_pattern_size = 50 # mm, centre-to-centre square pattern\nhole_offset_x = hole_pattern_size / 2  # 25 mm\nhole_offset_y = hole_pattern_size / 2  # 25 mm\n\nwith BuildPart() as plate:\n    # Step 1: Create base box centred on XY, from Z=0 to Z=8\n    Box(plate_length, plate_width, plate_thickness,\n        align=(Align.CENTER, Align.CENTER, Align.MIN))\n\n    # Step 2 & 3: Subtract four through-holes at (\u00b125, \u00b125)\n    hole_centers = [\n        (hole_offset_x,  hole_offset_y),\n        (-hole_offset_x,  hole_offset_y),\n        (hole_offset_x, -hole_offset_y),\n        (-hole_offset_x, -hole_offset_y),\n    ]\n    with Locations(*[(x, y, 0) for x, y in hole_centers]):\n        Cylinder(\n            radius=hole_diameter / 2,\n            height=plate_thickness,\n            align=(Align.CENTER, Align.CENTER, Align.MIN),\n            mode=Mode.SUBTRACT\n        )\n\nresult = plate.part",
