   "code": "from build123d import *\n\n# Governing dimensions\nplate_length = 70       # mm\nplate_width = 70        # mm\nplate_thickness = 12    # mm\ncounterbore_diameter = 20  # mm\ncounterbore_depth = 6   # mm\nthrough_hole_diameter = 11  # mm\n\n# Step 1: Create base plate centred at XY origin, bottom face at Z=0\nwith BuildPart() as part:\n    # Base plate\n    with BuildSketch(Plane.XY):\n        Rectangle(plate_length, plate_width)\n    extrude(amount=plate_thickness)\n\n    # Step 2 & 3: Subtract counterbore pocket from top face (\u00d820, 6 mm deep)\n    with BuildSketch(part.faces().sort_by(Axis.Z)[-1]):\n        Circle(counterbore_diameter / 2)\n    extrude(amount=-counterbore_depth, mode=Mode.SUBTRACT)\n\n    # Step 4: Subtract through-hole (\u00d811, full depth)\n    with BuildSketch(part.faces().sort_by(Axis.Z)[-1]):\n        Circle(through_hole_diameter / 2)\n    extrude(amount=-plate_thickness, mode=Mode.SUBTRACT)\n\nresult = part.part",
