   "code": "from build123d import *\n\n# Governing dimensions\nplate_length = 70\nplate_width = 70\nplate_thickness = 12\ncounterbore_diameter = 20\ncounterbore_depth = 6\nthrough_hole_diameter = 11\nhole_centre_x = 0\nhole_centre_y = 0\n\n# Step 1: Create base plate\nwith BuildPart() as part:\n    # Base plate: 70x70x12, bottom at Z=0, top at Z=12\n    with BuildSketch(Plane.XY.offset(0)):\n        Rectangle(plate_length, plate_width)\n    extrude(amount=plate_thickness)\n\n    # Step 2 & 3: Cut counterbore from top face (blind, 6mm deep)\n    with BuildSketch(Plane.XY.offset(plate_thickness)):\n        Circle(counterbore_diameter / 2)\n    extrude(amount=-counterbore_depth, mode=Mode.SUBTRACT)\n\n    # Step 4: Cut through-hole (full thickness)\n    with BuildSketch(Plane.XY.offset(plate_thickness)):\n        Circle(through_hole_diameter / 2)\n    extrude(amount=-plate_thickness, mode=Mode.SUBTRACT)\n\nresult = part.part",
