   "code": "from build123d import *\n\n# Governing dimensions\nplate_length = 70      # mm\nplate_width = 70       # mm\nplate_thickness = 12   # mm\nthru_hole_diameter = 11    # mm\ncounterbore_diameter = 20  # mm\ncounterbore_depth = 6      # mm\n\n# Step 1: Create base plate centred at origin\nwith BuildPart() as part:\n    Box(plate_length, plate_width, plate_thickness, align=(Align.CENTER, Align.CENTER, Align.CENTER))\n\n    # Step 3: Cut through-hole (full depth, centred at XY origin)\n    Cylinder(\n        radius=thru_hole_diameter / 2,\n        height=plate_thickness,\n        align=(Align.CENTER, Align.CENTER, Align.CENTER),\n        mode=Mode.SUBTRACT\n    )\n\n    # Step 4: Cut counterbore pocket (\u00d820 mm, 6 mm deep from top face)\n    # Top face is at Z = +plate_thickness/2 = +6\n    # Counterbore extends from Z = +6 down to Z = 0\n    # Centre of counterbore cylinder at Z = +6 - 6/2 = +3\n    with Locations((0, 0, plate_thickness / 2 - counterbore_depth / 2)):\n        Cylinder(\n            radius=counterbore_diameter / 2,\n            height=counterbore_depth,\n            align=(Align.CENTER, Align.CENTER, Align.CENTER),\n            mode=Mode.SUBTRACT\n        )\n\nresult = part.part",
