   "code": "from build123d import *\n\n# Parameters\nflange_diameter = 60\nflange_thickness = 6\nhub_diameter = 30\noverall_length = 30\nbore_diameter = 20\n\nhub_length = overall_length - flange_thickness  # 24 mm\n\nwith BuildPart() as bp:\n    # Create flange (base cylinder)\n    with BuildSketch(Plane.XY) as flange_sketch:\n        Circle(flange_diameter / 2)\n    extrude(amount=flange_thickness)\n\n    # Create hub on top of flange\n    with BuildSketch(Plane.XY.offset(flange_thickness)) as hub_sketch:\n        Circle(hub_diameter / 2)\n    extrude(amount=hub_length)\n\n    # Bore through entire part\n    with BuildSketch(Plane.XY) as bore_sketch:\n        Circle(bore_diameter / 2)\n    extrude(amount=overall_length, mode=Mode.SUBTRACT)\n\nresult = bp.part",
