   "code": "from build123d import *\n\n# Governing dimensions\nflange_diameter = 60      # mm\nflange_thickness = 6      # mm\nhub_diameter = 30         # mm\noverall_length = 30       # mm\nbore_diameter = 20        # mm\n\nhub_height = overall_length - flange_thickness  # 24 mm\n\n# Step 1: Flange cylinder (bottom face at Z=0, top face at Z=6)\nwith BuildPart() as flange_part:\n    with Locations((0, 0, flange_thickness / 2)):\n        Cylinder(radius=flange_diameter / 2, height=flange_thickness)\n\n# Step 2: Hub cylinder (bottom face at Z=6, top face at Z=30)\nwith BuildPart() as hub_part:\n    with Locations((0, 0, flange_thickness + hub_height / 2)):\n        Cylinder(radius=hub_diameter / 2, height=hub_height)\n\n# Step 3: Union flange + hub\ncombined = flange_part.part + hub_part.part\n\n# Step 4: Bore (full length, centred at Z=15)\nwith BuildPart() as bore_part:\n    with Locations((0, 0, overall_length / 2)):\n        Cylinder(radius=bore_diameter / 2, height=overall_length)\n\n# Boolean subtract bore from combined body\nresult = combined - bore_part.part",
