   "code": "from build123d import *\n\n# Governing dimensions\nflange_od = 60\nflange_t = 6\nhub_od = 30\nhub_h = 24\ntotal_l = 30\nbore_d = 20\n\n# Step 1: Create the flange cylinder (Z = 0 to Z = 6)\nwith BuildPart() as flange_part:\n    with Locations((0, 0, 0)):\n        Cylinder(radius=flange_od / 2, height=flange_t, align=(Align.CENTER, Align.CENTER, Align.MIN))\n\n# Step 2: Create the hub cylinder (Z = 6 to Z = 30)\nwith BuildPart() as hub_part:\n    with Locations((0, 0, flange_t)):\n        Cylinder(radius=hub_od / 2, height=hub_h, align=(Align.CENTER, Align.CENTER, Align.MIN))\n\n# Step 3: Union flange and hub\nwith BuildPart() as bushing:\n    with Locations((0, 0, 0)):\n        Cylinder(radius=flange_od / 2, height=flange_t, align=(Align.CENTER, Align.CENTER, Align.MIN))\n    with Locations((0, 0, flange_t)):\n        Cylinder(radius=hub_od / 2, height=hub_h, align=(Align.CENTER, Align.CENTER, Align.MIN))\n    # Step 4 & 5: Subtract the bore through the entire part\n    with Locations((0, 0, 0)):\n        Cylinder(radius=bore_d / 2, height=total_l, align=(Align.CENTER, Align.CENTER, Align.MIN), mode=Mode.SUBTRACT)\n\nresult = bushing.part",
   "stl": "models/a274.stl",
   "ref_stl": "models/ref_T2-flanged-bushing.stl"
