   "code": "from build123d import *\n\n# Governing dimensions\nbore_diameter    = 20   # mm\nflange_diameter  = 60   # mm\nflange_thickness = 6    # mm\nhub_diameter     = 30   # mm\noverall_length   = 30   # mm\nhub_length       = overall_length - flange_thickness  # 24 mm\n\n# Step 1: Flange disc \u2014 bottom face at Z=0, top face at Z=6\nwith BuildPart() as flange_part:\n    with Locations((0, 0, flange_thickness / 2)):\n        Cylinder(radius=flange_diameter / 2, height=flange_thickness)\n\n# Step 2: Hub cylinder \u2014 bottom face at Z=6, top face at Z=30\nwith BuildPart() as hub_part:\n    with Locations((0, 0, flange_thickness + hub_length / 2)):\n        Cylinder(radius=hub_diameter / 2, height=hub_length)\n\n# Step 3: Union flange + hub\nwith BuildPart() as combined:\n    add(flange_part.part)\n    add(hub_part.part)\n\n# Step 4: Through bore \u2014 full length from Z=0 to Z=30\nwith BuildPart() as bushing:\n    add(combined.part)\n    with Locations((0, 0, overall_length / 2)):\n        Cylinder(radius=bore_diameter / 2, height=overall_length, mode=Mode.SUBTRACT)\n\nresult = bushing.part",
