   "code": "from build123d import *\n\n# Parameters\nthickness = 8       # plate thickness\nbase_length = 60    # X direction\nbase_width = 40     # Y direction\nwall_height = 40    # overall height of vertical wall (including base overlap)\n\n# Build the L-bracket from two rectangular boxes\n\n# Horizontal base plate: 60 x 40 x 8, sitting on Z=0\nbase_plate = Box(base_length, base_width, thickness, align=(Align.MIN, Align.MIN, Align.MIN))\n\n# Vertical wall: 60 wide (X), 8 thick (Y), rises from one 60mm edge of base\n# The wall sits at Y=0 edge of the base, extending in Y from 0 to thickness=8\n# and in Z from 0 to wall_height=40\nwall_plate = Box(base_length, thickness, wall_height, align=(Align.MIN, Align.MIN, Align.MIN))\n# wall_plate occupies X: 0..60, Y: 0..8, Z: 0..40\n\n# Combine\nbracket = base_plate + wall_plate\n\n# Drill hole through base plate (vertical axis, Z direction)\n# Centred 30 mm along width (X=30) and 28 mm from the wall (Y direction)\n# \"28 mm from the wall\": the wall is at Y=0..8, so 28 mm from the wall face (Y=0) \u2192 Y=28\n# but let's interpret \"28 mm from the wall\" as from the inner face of the wall (Y=8)\n# That would place it at Y = 8 + 28 = 36, which is close to the edge (40mm).\n# More naturally: 28 mm from the wall means from the wall's inner surface \u2192 Y = 8 + 20 = 28\n# Re-reading: \"centred 30 mm along the width and 28 mm from the wall\"\n# Width of base is 40mm (Y direction). 28 mm from the wall (Y=0 face) \u2192 Y=28\nhole_base_x = 30.0\nhole_base_y = 28.0\n\nwith BuildPart() as bp:\n    add(bracket)\n    # Base hole - vertical (Z axis)\n    with Locations((hole_base_x, hole_base_y, 0)):\n        Hole(radius=4, depth=thickness)\n\nbracket_with_base_hole = bp.part\n\n# Drill hole through vertical wall (horizontal axis, Y direction)\n# Centred 30 mm along width (X=30) and 24 mm above base bottom (Z=24)\nhole_wall_x = 30.0\nhole_wall_z = 24.0\n\nwith BuildPart() as bp2:\n    add(bracket_with_base_hole)\n    # Wall hole - through Y axis, wall is at Y=0..8\n    # Create a cylinder along Y axis through the wall\n    with Locations((hole_wall_x, 0, hole_wall_z)):\n        hole_cyl = Cylinder(radius=4, height=thickness, align=(Align.CENTER, Align.MIN, Align.CENTER))\n    # Subtract the cylinder\n    result_solid = bp2.part - hole_cyl\n\n# Use BuildPart subtract approach more cleanly\nwith BuildPart() as final_bp:\n    add(bracket_with_base_hole)\n    with Locations((hole_wall_x, thickness / 2, hole_wall_z)):\n        Hole(radius=4, depth=thickness)\n\nresult = final_bp.part",
