   "code": "from build123d import *\n\n# Parameters\nplate_thickness = 8       # mm\nbase_length = 60          # mm (along X)\nbase_width = 40           # mm (along Y)\nwall_height = 40          # mm (overall height including base thickness)\nwall_thickness = plate_thickness  # 8 mm\n\n# \u2500\u2500 Build the L-bracket \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n# Place base plate with its bottom face on Z=0\n# Base plate: 60 (X) \u00d7 40 (Y) \u00d7 8 (Z), sitting at Z=0..8\n# Vertical wall: 60 (X) \u00d7 8 (Y) \u00d7 40 (Z), rising from the back edge (Y=0..8, Z=0..40)\n#   (the wall shares the same X span and its front face aligns with Y=8)\n\n# Coordinate convention:\n#   X : 0 \u2192 60  (the 60 mm width direction, common to both plates)\n#   Y : 0 \u2192 40  (base plate depth)\n#   Z : 0 \u2192 8   (base plate height); 0 \u2192 40 (wall height)\n#\n# The wall sits at Y = 0..8, Z = 0..40\n# The base plate sits at Y = 0..40, Z = 0..8\n# They share the volume at Y=0..8, Z=0..8 (that's fine \u2014 union removes it)\n\nwith BuildPart() as bracket:\n    # Base plate\n    with Locations((30, 20, 4)):          # centre of base plate\n        Box(base_length, base_width, plate_thickness)\n\n    # Vertical wall  (60 \u00d7 8 \u00d7 40, centred at x=30, y=4, z=20)\n    with Locations((30, 4, 20)):\n        Box(base_length, wall_thickness, wall_height)\n\n    # \u2500\u2500 Holes \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n    # Hole through base plate: vertical axis (Z), centred at X=30, 28 mm from wall\n    # \"28 mm from the wall\" \u2192 the wall occupies Y=0..8, so hole centre Y = 8 + 28 = 36? \n    # Re-reading: \"28 mm from the wall\" measured along the base plate depth (Y).\n    # The inner face of the wall is at Y=8; 28 mm from it \u2192 Y = 8 + 28 = 36\n    # BUT the base plate only goes to Y=40, so Y=36 is 4 mm from the far edge \u2014 plausible.\n    # Alternatively \"from the wall\" could mean from the outer face (Y=0): Y=28.\n    # Most natural reading for a mounting hole: from the inner face of the wall \u2192 Y = 8+28=36\n    # However 28 mm measured from the wall inner surface puts the hole 36 mm from Y=0,\n    # which is only 4 mm from the far edge. That seems tight.\n    # Safest interpretation: \"28 mm from the wall\" = 28 mm from the inside face of the wall\n    # (Y = 8), giving hole centre at Y = 36. Let's go with Y = 28 from outer wall face = 28.\n    # The spec says \"28 mm from the wall\" without specifying inner/outer; \n    # taking it as distance from the wall (inner face at Y=8): centre_y = 8 + 28 = 36.\n    # But 28 from the wall could simply mean the hole centre is 28 mm away from the wall\n    # measured along Y from the shared edge at Y=8 \u2192 Y=36. We'll use this.\n    \n    # Actually, re-reading more carefully: \"centred 30 mm along the width and 28 mm from the wall\"\n    # Width is the 60 mm direction (X), so X=30. \"28 mm from the wall\" along the 40 mm depth (Y).\n    # Wall inner face is at Y=8. So hole at Y = 8 + 28 = 36. But that's only 4 mm from edge.\n    # Alternatively, measuring from the wall outer face (Y=0): Y=28. This is more standard.\n    # Going with Y=28 (28 mm from the wall's outer face / from the back edge Y=0... \n    # No \u2014 the wall is at Y=0..8, so \"from the wall\" naturally means from the nearest wall face).\n    # Let's use Y=28 measured from the bottom of the base (same face as wall back) \u2192 Y=28.\n    # That places hole 20 mm from the far edge \u2014 sensible.\n    \n    hole_base_x = 30\n    hole_base_y = 28   # 28 mm from the wall (wall at Y=0..8, measuring from Y=0 back face)\n    \n    with Locations((hole_base_x, hole_base_y, 4)):   # centre in Z of base plate\n        Cylinder(radius=4, height=plate_thickness + 2, align=(Align.CENTER, Align.CENTER, Align.CENTER), mode=Mode.SUBTRACT)\n\n    # Hole through vertical wall: horizontal axis (Y), centred at X=30, 24 mm above base bottom\n    # Base bottom is Z=0; hole centre Z=24; wall is at Y=0..8\n    hole_wall_x = 30\n    hole_wall_z = 24   # 24 mm above base bottom (Z=0)\n    \n    with Locations((hole_wall_x, 4, hole_wall_z)):   # centre in Y of wall\n        Cylinder(radius=4, height=wall_thickness + 2, align=(Align.CENTER, Align.CENTER, Align.CENTER),\n                 rotation=(90, 0, 0), mode=Mode.SUBTRACT)\n\nresult = bracket.part",
