   "code": "from build123d import *\n\n# Parameters\nplate_thickness = 8\nbase_length = 60  # along X\nbase_width = 40   # along Y\nwall_height = 40  # overall height (includes base thickness? No - \"overall height of 40mm\")\n# The wall rises from one 60mm edge of the base to an overall height of 40mm\n# So wall plate: 60mm wide x (40mm - 8mm) = 32mm tall? \n# Actually \"overall height of 40mm\" means from bottom of base to top of wall = 40mm\n# Base is 8mm thick, so wall height above base top = 40 - 8 = 32mm\n# But wall thickness = 8mm, wall width = 60mm\n\n# Let's set up coordinate system:\n# Base plate: lies in XY plane, from Y=0 to Y=40, X=0 to X=60, Z=0 to Z=8\n# Wall: rises from the Y=0 edge (one 60mm edge), \n#        X=0 to X=60, Y=0 to Y=8 (thickness), Z=0 to Z=40\n\n# Base plate\nbase_plate = Box(base_length, base_width, plate_thickness)\n# Center of Box is at origin by default, so it spans:\n# X: -30 to 30, Y: -20 to 20, Z: -4 to 4\n# Move base to sit at Z=0 bottom:\nbase_plate = base_plate.move(Location((0, 0, plate_thickness/2)))\n# Now base: X:-30..30, Y:-20..20, Z:0..8\n\n# Wall plate: 60mm wide (X), 8mm thick (Y), 40mm tall (Z)\n# Positioned at Y=-20 to Y=-12 (front edge of base), Z=0 to Z=40\nwall_plate = Box(base_length, plate_thickness, wall_height)\n# Default center at origin: X:-30..30, Y:-4..4, Z:-20..20\n# Move so it sits at Z=0 bottom and Y=-20 to Y=-12:\nwall_plate = wall_plate.move(Location((0, -base_width/2 + plate_thickness/2, wall_height/2)))\n# Y center = -20 + 4 = -16, so Y: -20 to -12 \u2713\n# Z center = 20, so Z: 0 to 40 \u2713\n\n# Union the two plates\nbracket = base_plate + wall_plate\n\n# Hole through base plate (vertical axis, along Z)\n# \"centred 30mm along the width and 28mm from the wall\"\n# Width of base = 40mm (Y direction), center along X = 30mm from one end\n# \"30mm along the width\" -> X position: from X=-30, go 30mm -> X=0 (center)\n# Wait, \"30mm along the width\" of 60mm base_length means X=0 (center)\n# \"28mm from the wall\" -> wall is at Y=-20 edge, so Y = -20 + 28 = 8\n# Hole center: X=0, Y=8, through Z (vertical)\nbase_hole_x = 0  # 30mm from X=-30 edge -> X=0\nbase_hole_y = -base_width/2 + 28  # 28mm from wall edge = -20 + 28 = 8\n\nbase_hole = Cylinder(radius=4, height=plate_thickness + 2)\nbase_hole = base_hole.move(Location((base_hole_x, base_hole_y, plate_thickness/2)))\n\n# Hole through vertical wall (horizontal axis, along Y)\n# \"centred 30mm along the width\" -> X=0 (center of 60mm width)\n# \"24mm above the base bottom\" -> Z=24\nwall_hole_x = 0\nwall_hole_z = 24\n\nwall_hole = Cylinder(radius=4, height=plate_thickness + 2)\n# Rotate to align with Y axis\nwall_hole = wall_hole.rotate(Axis.X, 90)\nwall_hole = wall_hole.move(Location((wall_hole_x, -base_width/2 + plate_thickness/2, wall_hole_z)))\n\n# Subtract holes\nresult = bracket - base_hole - wall_hole",
