   "code": "from build123d import *\n\n# Governing dimensions\nbase_length = 60      # X\nbase_depth = 40       # Y\nbase_thickness = 8    # Z\nwall_width = 60       # X (same as base_length)\nwall_height = 40      # Z overall\nwall_thickness = 8    # Y\nhole_diameter = 8\n\nbase_hole_x = 30      # X centre of base hole\nbase_hole_y = 28      # Y centre of base hole (from wall face)\nwall_hole_x = 30      # X centre of wall hole\nwall_hole_z = 24      # Z centre of wall hole (from base bottom)\n\n# Create base plate: X:0->60, Y:0->40, Z:0->8\nwith BuildPart() as bp:\n    # Base plate\n    with Locations((base_length/2, base_depth/2, base_thickness/2)):\n        Box(base_length, base_depth, base_thickness)\n    \n    # Vertical wall: X:0->60, Y:0->8, Z:0->40\n    with Locations((wall_width/2, wall_thickness/2, wall_height/2)):\n        Box(wall_width, wall_thickness, wall_height, mode=Mode.ADD)\n    \n    # Drill hole through base plate (vertical, Z-axis)\n    # Centre at (30, 28), through Z:0->8\n    with Locations((base_hole_x, base_hole_y, base_thickness/2)):\n        Cylinder(radius=hole_diameter/2, height=base_thickness, mode=Mode.SUBTRACT)\n    \n    # Drill hole through vertical wall (horizontal, Y-axis)\n    # Centre at (30, ?, 24), Y:0->8\n    with Locations((wall_hole_x, wall_thickness/2, wall_hole_z)):\n        Cylinder(radius=hole_diameter/2, height=wall_thickness,\n                 rotation=(90, 0, 0), mode=Mode.SUBTRACT)\n\nresult = bp.part",
