   "code": "from build123d import *\n\n# Governing dimensions\nbase_length = 60        # X\nbase_depth = 40         # Y (from Y=0 to Y=+40)\nbase_thickness = 8      # Z\nwall_width = 60         # X (same as base_length)\nwall_thickness = 8      # Y (extends from Y=0 to Y=-8)\nwall_height = 40        # Z (overall height, includes base thickness region)\nhole_diameter = 8\nhole_radius = hole_diameter / 2\n\n# Hole positions\nbase_hole_x = 30        # X centre of base hole\nbase_hole_y_from_wall = 28  # distance from inner wall face (Y=0) toward +Y\nwall_hole_x = 30        # X centre of wall hole\nwall_hole_z = 24        # Z centre of wall hole above base bottom\n\n# Step 1: Base Plate \u2014 60 x 40 x 8, bottom-left-front at origin\n# Occupies X: 0..60, Y: 0..40, Z: 0..8\nwith BuildPart() as bp:\n    with Locations((base_length/2, base_depth/2, base_thickness/2)):\n        Box(base_length, base_depth, base_thickness)\n\nbase_solid = bp.part\n\n# Step 2: Vertical Wall \u2014 60 x 8 x 40\n# Occupies X: 0..60, Y: -8..0, Z: 0..40\nwith BuildPart() as wp:\n    with Locations((wall_width/2, -wall_thickness/2, wall_height/2)):\n        Box(wall_width, wall_thickness, wall_height)\n\nwall_solid = wp.part\n\n# Union base and wall\ncombined = base_solid.fuse(wall_solid)\n\n# Step 3: Base hole \u2014 vertical axis, centre at (30, 28, through base thickness)\n# Cylinder along Z, passing through Z=0..8\nwith BuildPart() as bh:\n    with Locations((base_hole_x, base_hole_y_from_wall, base_thickness/2)):\n        Cylinder(hole_radius, base_thickness + 2)  # slight oversize to ensure clean cut\n\nbase_hole_solid = bh.part\ncombined = combined.cut(base_hole_solid)\n\n# Step 4: Wall hole \u2014 horizontal axis (Y), centre at (30, through wall, Z=24)\n# Cylinder along Y, passing through Y=-8..0\nwith BuildPart() as wh:\n    with Locations((wall_hole_x, -wall_thickness/2, wall_hole_z)):\n        Cylinder(hole_radius, wall_thickness + 2, rotation=(90, 0, 0))\n\nwall_hole_solid = wh.part\ncombined = combined.cut(wall_hole_solid)\n\nresult = combined",
