   "code": "from build123d import *\n\n# Governing dimensions\nbase_length = 60      # X\nbase_depth = 40       # Y\nbase_thickness = 8    # Z\nwall_height = 40      # Z total (from Z=0 to Z=40)\nwall_thickness = 8    # Y\nhole_diameter = 8\n\nbase_hole_x = 30      # X centre\nbase_hole_y = 12      # Y centre (28 mm from wall face at Y=40 \u2192 Y=40-28=12)\nwall_hole_x = 30      # X centre\nwall_hole_z = 24      # Z centre\n\n# Step 1: Base plate \u2014 60 x 40 x 8, bottom at Z=0\nbase_plate = Box(base_length, base_depth, base_thickness,\n                 align=(Align.MIN, Align.MIN, Align.MIN))\n\n# Step 2: Vertical wall \u2014 60 x 8 x 40, back of base (Y=32 to Y=40), Z=0 to Z=40\nwall = Box(base_length, wall_thickness, wall_height,\n           align=(Align.MIN, Align.MIN, Align.MIN))\nwall = wall.moved(Location((0, base_depth - wall_thickness, 0)))\n\n# Step 3: Union\nbracket = base_plate + wall\n\n# Step 4: Drill hole through base plate (vertical, Z-axis)\nbase_hole = Cylinder(radius=hole_diameter / 2, height=base_thickness + 2,\n                     align=(Align.CENTER, Align.CENTER, Align.MIN))\nbase_hole = base_hole.moved(Location((base_hole_x, base_hole_y, -1)))\nbracket = bracket - base_hole\n\n# Step 5: Drill hole through vertical wall (horizontal, Y-axis)\n# Wall spans Y=32 to Y=40 (thickness=8), hole through Y direction\nwall_hole = Cylinder(radius=hole_diameter / 2, height=wall_thickness + 2,\n                     align=(Align.CENTER, Align.CENTER, Align.MIN))\n# Rotate to align with Y-axis\nwall_hole = wall_hole.rotate(Axis.X, 90)\n# Position at X=30, Z=24, Y spanning wall (Y=32 to Y=40)\nwall_hole = wall_hole.moved(Location((wall_hole_x, base_depth - wall_thickness - 1, wall_hole_z)))\nbracket = bracket - wall_hole\n\nresult = bracket",
