   "code": "from build123d import *\n\n# Parameters\ndisc_diameter = 80\ndisc_thickness = 16\nhub_diameter = 32\noverall_height = 36\nbore_diameter = 16\n\nhub_height = overall_height - disc_thickness  # 20 mm\n\nwith BuildPart() as pulley:\n    # Main disc\n    with BuildSketch(Plane.XY):\n        Circle(disc_diameter / 2)\n    extrude(amount=disc_thickness)\n    \n    # Hub extending above the disc\n    with BuildSketch(Plane.XY.offset(disc_thickness)):\n        Circle(hub_diameter / 2)\n    extrude(amount=hub_height)\n    \n    # Bore through entire part\n    with BuildSketch(Plane.XY):\n        Circle(bore_diameter / 2)\n    extrude(amount=overall_height, mode=Mode.SUBTRACT)\n\nresult = pulley.part",
