   "code": "from build123d import *\n\n# Governing dimensions\ndisc_diameter = 80\ndisc_thickness = 16\nhub_diameter = 32\nhub_extension = 20       # hub height above the disc\noverall_height = 36      # disc_thickness + hub_extension\nbore_diameter = 16\n\n# Step 1: Create disc cylinder (base at Z=0, top at Z=16)\nwith BuildPart() as disc_part:\n    with Locations((0, 0, 0)):\n        Cylinder(radius=disc_diameter / 2, height=disc_thickness, align=(Align.CENTER, Align.CENTER, Align.MIN))\n\n# Step 2: Create hub cylinder (base at Z=16, top at Z=36)\nwith BuildPart() as hub_part:\n    with Locations((0, 0, disc_thickness)):\n        Cylinder(radius=hub_diameter / 2, height=hub_extension, align=(Align.CENTER, Align.CENTER, Align.MIN))\n\n# Step 3: Union disc and hub\nwith BuildPart() as body_part:\n    with Locations((0, 0, 0)):\n        Cylinder(radius=disc_diameter / 2, height=disc_thickness, align=(Align.CENTER, Align.CENTER, Align.MIN))\n    with Locations((0, 0, disc_thickness)):\n        Cylinder(radius=hub_diameter / 2, height=hub_extension, align=(Align.CENTER, Align.CENTER, Align.MIN))\n\n# Step 4 & 5: Subtract bore through entire height\nwith BuildPart() as pulley_part:\n    with Locations((0, 0, 0)):\n        Cylinder(radius=disc_diameter / 2, height=disc_thickness, align=(Align.CENTER, Align.CENTER, Align.MIN))\n    with Locations((0, 0, disc_thickness)):\n        Cylinder(radius=hub_diameter / 2, height=hub_extension, align=(Align.CENTER, Align.CENTER, Align.MIN))\n    # Bore through full height\n    with Locations((0, 0, 0)):\n        Cylinder(radius=bore_diameter / 2, height=overall_height, align=(Align.CENTER, Align.CENTER, Align.MIN), mode=Mode.SUBTRACT)\n\nresult = pulley_part.part",
