   "code": "from build123d import *\n\n# Stepped cylindrical shaft\n# Total length: 120 mm\n# Central section: \u00d840 mm \u00d7 80 mm long\n# End bearing seats: \u00d830 mm \u00d7 20 mm long each\n# All coaxial along Z axis\n\nwith BuildPart() as shaft:\n    # Central section: 80 mm long, centered at z=0 \u2192 from z=-40 to z=+40\n    with Locations((0, 0, 0)):\n        Cylinder(radius=20, height=80)\n    \n    # Left bearing seat: \u00d830 mm \u00d7 20 mm, from z=-60 to z=-40\n    with Locations((0, 0, -50)):\n        Cylinder(radius=15, height=20)\n    \n    # Right bearing seat: \u00d830 mm \u00d7 20 mm, from z=+40 to z=+60\n    with Locations((0, 0, 50)):\n        Cylinder(radius=15, height=20)\n\nresult = shaft.part",
