   "code": "from build123d import *\n\n# Governing dimensions\ntotal_length = 120\nbearing_seat_diameter = 30\nbearing_seat_length = 20\ncentral_diameter = 40\ncentral_length = 80\n\n# Z positions\nleft_seat_z_start = 0\nleft_seat_z_end = 20\ncentral_z_start = 20\ncentral_z_end = 100\nright_seat_z_start = 100\nright_seat_z_end = 120\n\nshoulder_step_height = (central_diameter - bearing_seat_diameter) / 2  # 5 mm\n\n# Build each cylinder section\nwith BuildPart() as shaft:\n    # Left bearing seat: Z = 0 to 20\n    with Locations((0, 0, left_seat_z_start)):\n        Cylinder(\n            radius=bearing_seat_diameter / 2,\n            height=bearing_seat_length,\n            align=(Align.CENTER, Align.CENTER, Align.MIN)\n        )\n    # Central body: Z = 20 to 100\n    with Locations((0, 0, central_z_start)):\n        Cylinder(\n            radius=central_diameter / 2,\n            height=central_length,\n            align=(Align.CENTER, Align.CENTER, Align.MIN),\n            mode=Mode.PRIVATE\n        )\n    add(shaft.part)  # ensure central cylinder is fused\n\n# Rebuild cleanly using explicit union approach\nleft_seat = Cylinder(\n    radius=bearing_seat_diameter / 2,\n    height=bearing_seat_length,\n    align=(Align.CENTER, Align.CENTER, Align.MIN)\n)\n\ncentral_body = Cylinder(\n    radius=central_diameter / 2,\n    height=central_length,\n    align=(Align.CENTER, Align.CENTER, Align.MIN)\n)\ncentral_body = central_body.moved(Location((0, 0, central_z_start)))\n\nright_seat = Cylinder(\n    radius=bearing_seat_diameter / 2,\n    height=bearing_seat_length,\n    align=(Align.CENTER, Align.CENTER, Align.MIN)\n)\nright_seat = right_seat.moved(Location((0, 0, right_seat_z_start)))\n\nresult = left_seat.fuse(central_body).fuse(right_seat)",
