   "code": "from build123d import *\n\n# Governing dimensions\ntotal_length = 120.0\ncentral_length = 80.0\ncentral_diameter = 40.0\nbearing_length = 20.0\nbearing_diameter = 30.0\n\ncentral_half_length = central_length / 2.0          # 40.0\ntotal_half_length = total_length / 2.0               # 60.0\nbearing_seat_centre_offset = central_half_length + bearing_length / 2.0  # 50.0\n\n# Central cylinder centred at origin along Z\ncentral = Cylinder(radius=central_diameter / 2.0, height=central_length)\n\n# Left bearing seat: centre at Z = -50\nleft_seat = Cylinder(\n    radius=bearing_diameter / 2.0,\n    height=bearing_length\n)\nleft_seat = left_seat.move(Location((0, 0, -bearing_seat_centre_offset)))\n\n# Right bearing seat: centre at Z = +50\nright_seat = Cylinder(\n    radius=bearing_diameter / 2.0,\n    height=bearing_length\n)\nright_seat = right_seat.move(Location((0, 0, +bearing_seat_centre_offset)))\n\n# Union all three\nresult = central + left_seat + right_seat",
