   "code": "from build123d import *\nfrom math import pi\n\n# Parameters\nouter_diameter = 30\ninner_diameter = 20\nlength = 40\n\n# Create outer cylinder\nouter_cylinder = Cylinder(radius=outer_diameter/2, height=length)\n\n# Create inner cylinder (hole)\ninner_cylinder = Cylinder(radius=inner_diameter/2, height=length)\n\n# Subtract inner cylinder from outer cylinder to create bushing\nbushing = outer_cylinder - inner_cylinder\n\n# Align so length is along +Z axis (already aligned by default Cylinder creation)\n# Rotate if necessary to meet conventional orientation\nresult = bushing\n\n# Check dimensions\nif __name__ == \"__main__\":\n    # This block would only run if executing directly\n    # For verification purposes, we can add bounding box check\n    bbox = result.bounding_box()\n    print(f\"X-dimension (outer diameter): {bbox.size.X:.2f} mm\")\n    print(f\"Y-dimension (outer diameter): {bbox.size.Y:.2f} mm\")\n    print(f\"Z-dimension (length): {bbox.size.Z:.2f} mm\")\n    \n    # Verify dimensions\n    outer_check = abs(bbox.size.X - outer_diameter) < 0.01\n    length_check = abs(bbox.size.Z - length) < 0.01\n    \n    print(f\"Outer diameter correct: {outer_check}\")\n    print(f\"Length correct: {length_check}\")",
