   "code": "from build123d import *\n\n# Parameters in mm\nouter_diameter = 45\nbore_diameter = 25\nwidth = 15\n\n# Create the shaft collar as a cylinder with a bore\nwith BuildPart() as collar:\n    # Outer cylinder\n    Cylinder(radius=outer_diameter/2, height=width)\n    \n    # Create bore by subtracting an inner cylinder\n    # Use extrude with SUBTRACT mode to ensure full depth\n    with BuildSketch(Plane.XY) as bore_sketch:\n        Circle(radius=bore_diameter/2)\n    extrude(bore_sketch.sketch, amount=width, mode=Mode.SUBTRACT)\n\n# Assign the result\nresult = collar.part",
