   "code": "from build123d import *\nfrom math import cos, sin, radians\n\nresult = extrude(\n    Circle(radius=120/2),\n    amount=14\n)\n\n# Create bore\nbore = extrude(\n    Circle(radius=40/2),\n    amount=14\n)\nresult -= bore\n\n# Create bolt holes\nfor i in range(6):\n    angle = radians(60 * i)\n    x = (95/2) * cos(angle)\n    y = (95/2) * sin(angle)\n    bolt_hole = extrude(\n        Circle(radius=11/2),\n        amount=14\n    )\n    bolt_hole = Pos(x, y) * bolt_hole\n    result -= bolt_hole",
