   "code": "from build123d import *\nfrom math import cos, sin, pi\n\n# Parameters\nouter_diameter = 120\nbore_diameter = 40\nbolt_hole_diameter = 11\nbolt_circle_diameter = 95\nnum_bolts = 6\nthickness = 14\n\n# Create the base flange plate with thickness along +Z\nresult = Cylinder(radius=outer_diameter/2, height=thickness)\n\n# Subtract the bore - make it taller than flange and centered\nbore = Cylinder(radius=bore_diameter/2, height=thickness + 2, align=(Align.CENTER, Align.CENTER, Align.CENTER))\nresult -= bore\n\n# Create and subtract bolt holes - make them taller than flange and centered\nbolt_hole_radius = bolt_hole_diameter / 2\nfor i in range(num_bolts):\n    angle = 360 * i / num_bolts\n    x = (bolt_circle_diameter / 2) * cos(pi * angle / 180)\n    y = (bolt_circle_diameter / 2) * sin(pi * angle / 180)\n    bolt_hole = Cylinder(radius=bolt_hole_radius, height=thickness + 2, align=(Align.CENTER, Align.CENTER, Align.CENTER))\n    bolt_hole = Pos(x, y, thickness/2) * bolt_hole\n    result -= bolt_hole",
