   "code": "from build123d import *\nfrom math import cos, sin, radians\n\n# Parameters\nouter_diameter = 120\nbore_diameter = 40\nbolt_hole_diameter = 11\nbolt_circle_diameter = 95\nthickness = 14\nnum_bolts = 6\n\n# Create flange plate\nwith BuildPart() as flange:\n    # Main circular plate - create as cylinder\n    Cylinder(radius=outer_diameter/2, height=thickness, align=Align.CENTER)\n    \n    # Subtract central bore (through hole)\n    with BuildSketch(Plane.XY):\n        Circle(bore_diameter/2)\n    extrude(amount=thickness, mode=Mode.SUBTRACT, both=True)\n    \n    # Create bolt holes\n    for i in range(num_bolts):\n        angle = 360/num_bolts * i\n        x = bolt_circle_diameter/2 * cos(radians(angle))\n        y = bolt_circle_diameter/2 * sin(radians(angle))\n        \n        # Create through hole\n        with BuildSketch(Plane(origin=(x, y, 0), z_dir=(0, 0, 1))):\n            Circle(bolt_hole_diameter/2)\n        extrude(amount=thickness, mode=Mode.SUBTRACT, both=True)\n\nresult = flange.part",
   "stl": "models/a320.stl",
   "ref_stl": "models/ref_T1-flange-6bolt.stl"
