   "code": "import build123d as bd\nfrom build123d import *\nfrom math import pi\n\nwith BuildPart() as part:\n    # Overall part height is 30 mm\n    total_height = 30\n    flange_thickness = 6\n    hub_height = total_height - flange_thickness\n\n    # Flange: diameter 60 mm, thickness 6 mm\n    with BuildSketch() as flange_sketch:\n        Circle(radius=60/2)\n    extrude(amount=flange_thickness)\n\n    # Hub: outer diameter 30 mm, extending above flange\n    # Start at top of flange (Z=6)\n    with BuildSketch(Plane(origin=(0,0,flange_thickness))) as hub_sketch:\n        Circle(radius=30/2)\n    extrude(amount=hub_height)\n\n    # Bore: \u00d820 mm through entire part (Z=0 to Z=30)\n    # Create bore as a separate solid and subtract\n    with BuildPart() as bore_builder:\n        Cylinder(radius=20/2, height=total_height)\n    \n    # Get the bore solid from the builder\n    bore = bore_builder.part\n    \n    # Subtract bore from the main part\n    part.part -= bore\n\nresult = part.part",
