   "code": "import build123d as bd\nfrom build123d import *\nimport math\n\n# Parameters\nflange_diameter = 60.0\nflange_thickness = 6.0\nhub_outer_diameter = 30.0\noverall_length = 30.0\nbore_diameter = 20.0\n\n# Calculate hub height\nhub_height = overall_length - flange_thickness\n\n# Create the flange\nflange = Cylinder(\n    radius=flange_diameter / 2,\n    height=flange_thickness,\n    align=(Align.CENTER, Align.CENTER, Align.MIN)\n)\n\n# Create the hub\nhub = Cylinder(\n    radius=hub_outer_diameter / 2,\n    height=hub_height,\n    align=(Align.CENTER, Align.CENTER, Align.MIN)\n)\n\n# Position hub on top of flange using locate\nhub = hub.locate(Location((0, 0, flange_thickness)))\n\n# Combine flange and hub\nsolid = flange + hub\n\n# Create bore cylinder (subtractive)\nbore = Cylinder(\n    radius=bore_diameter / 2,\n    height=overall_length,\n    align=(Align.CENTER, Align.CENTER, Align.MIN)\n)\n\n# Subtract bore\nresult = solid - bore",
