   "cds": null,
   "code": "import build123d as bd\n\n# Dimensions\nbase_width = 60.0\nbase_depth = 40.0\nwall_height = 40.0\nplate_thickness = 8.0\n\nhole_diameter = 8.0\nbase_hole_x_offset = base_width / 2  # 30 mm from wall side\nbase_hole_y_offset = 28.0  # from wall edge\nwall_hole_z_offset = 24.0  # above base bottom (from z=0)\nwall_hole_x_offset = base_width / 2  # centered along width\n\nwith bd.BuildPart() as part:\n    # Base plate\n    with bd.BuildSketch() as base_sketch:\n        bd.Rectangle(base_width, base_depth)\n    bd.extrude(amount=plate_thickness)\n    \n    # Vertical wall\n    # Position the wall sketch on the top face of base plate, aligned with one edge\n    wall_plane = bd.Plane(\n        origin=(0, 0, plate_thickness),\n        x_dir=(1, 0, 0),\n        z_dir=(0, -1, 0)\n    )\n    with bd.BuildSketch(wall_plane) as wall_sketch:\n        bd.Rectangle(base_width, wall_height)\n    bd.extrude(amount=plate_thickness)\n    \n    # Base hole (vertical)\n    base_hole_center = (base_hole_x_offset, base_hole_y_offset, plate_thickness/2)\n    with bd.BuildSketch(bd.Plane(origin=base_hole_center, z_dir=(0, 0, 1))):\n        bd.Circle(radius=hole_diameter/2)\n    bd.extrude(amount=-plate_thickness, mode=bd.Mode.SUBTRACT)\n    \n    # Wall hole (horizontal)\n    # Hole is centered 24 mm above base bottom (z=0), through wall thickness (Y direction)\n    wall_hole_center = (wall_hole_x_offset, plate_thickness, wall_hole_z_offset)\n    # Hole axis along Y direction (into the wall thickness)\n    with bd.BuildSketch(bd.Plane(origin=wall_hole_center, z_dir=(0, 1, 0))):\n        bd.Circle(radius=hole_diameter/2)\n    bd.extrude(amount=-plate_thickness, mode=bd.Mode.SUBTRACT)\n\nresult = part.part",
