   "code": "from build123d import *\n\n# Parameters\nthickness = 8\nbase_length = 60\nbase_width = 40\nwall_length = 60\nwall_height = 40\nhole_diameter = 8\nbase_hole_x_offset = 30  # From specification: centred 30 mm along the width\nbase_hole_y_offset = 28  # From specification: 28 mm from the wall\nwall_hole_x_offset = 30  # From specification: centred 30 mm along the width\nwall_hole_z_offset = 24  # From specification: 24 mm above the base bottom\n\n# Create base plate (centered at origin)\nbase = extrude(\n    Rectangle(width=base_length, height=base_width), \n    amount=thickness\n)\n\n# Create vertical wall at edge of base\nwall = extrude(\n    Rectangle(width=wall_length, height=wall_height),\n    amount=thickness\n)\n# Position wall at the edge of base (along X-axis)\nwall = Pos(base_length/2, 0, thickness) * Rot(90, 0, 0) * wall\n\n# Combine\nresult = base + wall\n\n# Base hole: vertical through base plate\n# Center positions relative to base center\nbase_hole_pos = Pos(\n    base_hole_x_offset - base_length/2,  # X offset from center\n    base_hole_y_offset - base_width/2,    # Y offset from center  \n    0\n)\nbase_hole = Cylinder(\n    radius=hole_diameter/2,\n    height=thickness,\n    align=(Align.CENTER, Align.CENTER, Align.MIN)\n)\nbase_hole = base_hole_pos * base_hole\nresult -= base_hole\n\n# Wall hole: horizontal through wall\n# Wall is positioned at base_length/2 along X, rotated 90\u00b0 around Y\n# So wall local coordinates: X along height, Y along thickness, Z along width\nwall_hole_pos = Pos(\n    wall_hole_z_offset - wall_height/2,  # X in wall coords (height direction)\n    0,                                   # Y in wall coords (thickness direction)\n    wall_hole_x_offset - wall_length/2   # Z in wall coords (width direction)\n)\nwall_hole = Cylinder(\n    radius=hole_diameter/2,\n    height=thickness,\n    align=(Align.CENTER, Align.CENTER, Align.MIN)\n)\n# Rotate cylinder to be horizontal (axis along wall thickness/Y)\nwall_hole = Rot(0, 90, 0) * wall_hole\nwall_hole = wall_hole_pos * wall_hole\n# Transform from wall local coords to global\nwall_hole = Pos(base_length/2, 0, thickness) * Rot(90, 0, 0) * wall_hole\nresult -= wall_hole\n\n# Final orientation: primary thickness along +Z\n# Currently base is in XY plane, wall extends in Z\n# This is already correct orientation",
