   "code": "import build123d as bd\n\nwith bd.BuildPart() as lbracket:\n    # Base plate: 60mm x 40mm, thickness 8mm, placed flat on XY plane\n    bd.Box(60, 40, 8)\n    \n    # Vertical wall: 60mm wide, 40mm tall, thickness 8mm\n    # Positioned at one 60mm edge of base, rising up\n    # Wall thickness is along X, width along Y, height along Z\n    # Base extends from x=-20 to x=20 (width=40)\n    # Wall center at x = 20 + 4 = 24 (half thickness past base edge), z = 20 (half height above base)\n    with bd.BuildPart(bd.Location((24, 0, 20))):\n        bd.Box(8, 60, 40)\n    \n    # Drill hole through base plate (vertical axis)\n    # Base dimensions: length=60 (X), width=40 (Y), height=8 (Z)\n    # Hole centered 30mm along width (Y direction): y = 30 - 60/2 = 30 - 30 = 0\n    # 28mm from wall: wall starts at x=20, so hole at x = 20 - 28 = -8\n    with bd.BuildSketch(bd.Plane(origin=(-8, 0, 0))):\n        bd.Circle(8/2)\n    bd.extrude(amount=8, mode=bd.Mode.SUBTRACT)\n    \n    # Drill hole through vertical wall (horizontal axis)\n    # Wall dimensions: length=8 (X), width=60 (Y), height=40 (Z)\n    # Hole centered 30mm along width (Y): y = 30 - 60/2 = 0\n    # 24mm above base bottom: base top is at z=8, wall bottom at z=0, so hole at z = 24\n    # Wall is at x from 20 to 28, hole goes through X direction\n    # Need to sketch on YZ plane at x position\n    with bd.BuildSketch(bd.Plane(origin=(24, 0, 24), x_dir=(0, 1, 0), z_dir=(-1, 0, 0))):\n        bd.Circle(8/2)\n    bd.extrude(amount=8, mode=bd.Mode.SUBTRACT)\n\nresult = lbracket.part",
