   "code": "import build123d as bd\n\n# Parameters\ntotal_length = 120  # mm\ncentral_diameter = 40  # mm\ncentral_length = 80  # mm\nseat_diameter = 30  # mm\nseat_length = 20  # mm\n\n# Verify that dimensions are consistent\nassert central_length + 2 * seat_length == total_length, \"Total length must equal sum of sections\"\n\n# Create the central section\ncentral_section = bd.Cylinder(\n    radius=central_diameter / 2,\n    height=central_length,\n    align=bd.Align.CENTER\n)\n\n# Create one bearing seat\nseat_section = bd.Cylinder(\n    radius=seat_diameter / 2,\n    height=seat_length,\n    align=bd.Align.CENTER\n)\n\n# Position the seat sections at each end\nleft_seat = bd.Location((0, 0, -total_length / 2 + seat_length / 2)) * seat_section\nright_seat = bd.Location((0, 0, total_length / 2 - seat_length / 2)) * seat_section\n\n# Combine all sections\nresult = bd.Compound(children=[central_section, left_seat, right_seat])\n\n# Verify the overall length\nwith bd.BuildPart() as check:\n    bd.add(result)\n    bbox = check.part.bounding_box()\n    actual_length = bbox.size.Z\n    print(f\"Total length: {actual_length:.2f} mm\")\n    \n    print(f\"Target total length: {total_length} mm\")\n    print(f\"Target central diameter: {central_diameter} mm\")\n    print(f\"Target seat diameter: {seat_diameter} mm\")\n    print(f\"Target central length: {central_length} mm\")\n    print(f\"Target seat length: {seat_length} mm\")",
