   "code": "from build123d import *\n\n# Parameters\nouter_diameter = 120\nbore_diameter = 40\nbolt_hole_diameter = 11\nbolt_circle_diameter = 95\nnum_bolts = 6\nplate_thickness = 14\n\n# Create the main flange plate\nflange = Cylinder(radius=outer_diameter/2, height=plate_thickness)\n\n# Subtract the central bore\nbore = Cylinder(radius=bore_diameter/2, height=plate_thickness)\nflange = flange - bore\n\n# Create and subtract the bolt holes\nbolt_radius = bolt_hole_diameter / 2\nbolt_circle_radius = bolt_circle_diameter / 2\n\nfor i in range(num_bolts):\n    angle = (360 / num_bolts) * i\n    # Convert angle to radians\n    angle_rad = angle * 3.14159265359 / 180\n    \n    # Calculate bolt hole position\n    x = bolt_circle_radius * (3.14159265359 * angle / 180) ** 0\n    y = bolt_circle_radius * (3.14159265359 * angle / 180) ** 0\n    \n    # Better approach: use cos and sin\n    import math\n    x = bolt_circle_radius * math.cos(math.radians(angle))\n    y = bolt_circle_radius * math.sin(math.radians(angle))\n    \n    # Create bolt hole at this position\n    bolt_hole = Cylinder(radius=bolt_radius, height=plate_thickness)\n    bolt_hole = bolt_hole.moved(Location((x, y, 0)))\n    \n    flange = flange - bolt_hole\n\nresult = flange",
