   "code": "from build123d import *\nimport math\n\n# Create a circular pipe flange with bolt holes\n# Outer diameter: 120 mm\n# Inner bore: 40 mm diameter\n# 6 bolt holes: 11 mm diameter on 95 mm PCD\n# Thickness: 14 mm\n\n# Start with the main circular flange\nflange = Cylinder(radius=60, height=14)\n\n# Subtract the central bore (40 mm diameter)\nbore = Cylinder(radius=20, height=14)\nflange = flange - bore\n\n# Create 6 bolt holes equally spaced on 95 mm PCD\npcd_radius = 47.5\nbolt_hole_radius = 5.5  # 11 mm diameter\nnum_holes = 6\n\nfor i in range(num_holes):\n    angle = i * 360 / num_holes\n    angle_rad = math.radians(angle)\n    x = pcd_radius * math.cos(angle_rad)\n    y = pcd_radius * math.sin(angle_rad)\n    \n    # Create bolt hole at this location using Location\n    bolt_hole = Cylinder(radius=bolt_hole_radius, height=14)\n    bolt_hole_location = Location(Vector(x, y, 0))\n    bolt_hole = bolt_hole.moved(bolt_hole_location)\n    \n    # Subtract from flange\n    flange = flange - bolt_hole\n\nresult = flange",
