   "code": "from build123d import *\nfrom math import cos, sin, pi\n\n# Parameters\nouter_diameter = 120\nbore_diameter = 40\nbolt_hole_diameter = 11\nbolt_circle_diameter = 95\nnum_bolts = 6\nplate_thickness = 14\n\n# Create the base circular plate\nbase_plate = Cylinder(radius=outer_diameter/2, height=plate_thickness)\n\n# Create the central bore\nbore = Cylinder(radius=bore_diameter/2, height=plate_thickness)\n\n# Create bolt holes\nbolt_holes = []\nbolt_radius = bolt_circle_diameter / 2\nhole_radius = bolt_hole_diameter / 2\n\nfor i in range(num_bolts):\n    angle = (360 / num_bolts) * i\n    # Position hole at the calculated angle on the bolt circle\n    hole = Cylinder(radius=hole_radius, height=plate_thickness)\n    # Translate to bolt circle position\n    hole = hole.translate((bolt_radius * cos(angle * pi / 180), \n                           bolt_radius * sin(angle * pi / 180), \n                           0))\n    bolt_holes.append(hole)\n\n# Subtract bore and all bolt holes from base plate\nresult = base_plate - bore\nfor hole in bolt_holes:\n    result = result - hole",
