   "code": "from build123d import *\n\n# Create a square mounting plate 80mm x 80mm x 8mm thick\nplate = Box(80, 80, 8, align=(Align.CENTER, Align.CENTER, Align.MIN))\n\n# Define hole positions: 50mm x 50mm square pattern centered on plate\n# Each hole center is 25mm from plate center along both axes\nhole_positions = [\n    (-25, -25),  # Bottom-left\n    (25, -25),   # Bottom-right\n    (-25, 25),   # Top-left\n    (25, 25),    # Top-right\n]\n\n# Create cylinders for the \u00d89mm holes and cut from plate\nresult = plate\nfor x, y in hole_positions:\n    hole = Cylinder(radius=4.5, height=10, align=(Align.CENTER, Align.CENTER, Align.MIN))\n    hole = hole.translate((x, y, -1))  # Extend slightly below plate for clean cutting\n    result = result.cut(hole)",
