   "code": "from build123d import *\n\n# Parameters\nplate_width = 80\nplate_height = 80\nplate_thickness = 8\nhole_diameter = 9\nhole_pattern_size = 50\n\n# Create the base plate\nplate = Box(plate_width, plate_height, plate_thickness, align=(Align.CENTER, Align.CENTER, Align.MIN))\n\n# Create the four holes\n# Holes are arranged in a 50mm x 50mm square pattern, centred on the plate\n# Each hole centre is 25mm from the plate centre along both axes\nhole_radius = hole_diameter / 2\nhole_offset = hole_pattern_size / 2\n\n# Define hole positions (relative to plate centre at Z=0)\nhole_positions = [\n    (-hole_offset, -hole_offset),  # Front-left\n    (hole_offset, -hole_offset),   # Front-right\n    (-hole_offset, hole_offset),   # Back-left\n    (hole_offset, hole_offset),    # Back-right\n]\n\n# Create cylinders for each hole, extending through the plate\nholes = []\nfor x, y in hole_positions:\n    hole = Cylinder(\n        radius=hole_radius,\n        height=plate_thickness * 2,  # Extend through the plate\n        align=(Align.CENTER, Align.CENTER, Align.MIN)\n    )\n    hole = hole.move(Location((x, y, -plate_thickness / 2)))\n    holes.append(hole)\n\n# Subtract holes from plate\nresult = plate\nfor hole in holes:\n    result = result - hole",
