   "code": "from build123d import *\n\n# Create a square plate 70 mm x 70 mm, 12 mm thick\nplate = Box(70, 70, 12, align=(Align.CENTER, Align.CENTER, Align.MIN))\n\n# Create a combined hole shape:\n# - Counterbore: \u00d820 mm (radius 10 mm), 6 mm deep from top (Z=6 to Z=12)\n# - Through-hole: \u00d811 mm (radius 5.5 mm), full thickness (Z=0 to Z=12)\n\n# Start with the through-hole cylinder (full height)\nthrough_hole = Cylinder(radius=5.5, height=12, align=(Align.CENTER, Align.CENTER, Align.MIN))\n\n# Create the counterbore (larger radius, only top 6 mm)\ncounterbore = Cylinder(radius=10, height=6, align=(Align.CENTER, Align.CENTER, Align.MAX))\ncounterbore = counterbore.translate((0, 0, 12))\n\n# Combine the holes\nhole = through_hole | counterbore\n\n# Subtract the combined hole from the plate\nresult = plate - hole",
