   "code": "from build123d import *\n\n# Parameters\nplate_width = 70  # mm\nplate_height = 70  # mm\nplate_thickness = 12  # mm\n\nthrough_hole_diameter = 11  # mm\ncounterbore_diameter = 20  # mm\ncounterbore_depth = 6  # mm\n\n# Create the base square plate\nplate = Box(plate_width, plate_height, plate_thickness, align=(Align.CENTER, Align.CENTER, Align.MIN))\n\n# Create the through-hole (cylinder through the entire thickness)\nthrough_hole = Cylinder(through_hole_diameter / 2, plate_thickness, align=(Align.CENTER, Align.CENTER, Align.MIN))\n\n# Create the counterbore (cylinder from top, depth of 6mm)\n# Position it at the top surface and going downward\ncounterbore = Cylinder(counterbore_diameter / 2, counterbore_depth, align=(Align.CENTER, Align.CENTER, Align.MAX))\ncounterbore = counterbore.translate((0, 0, plate_thickness))\n\n# Subtract both holes from the plate\nresult = plate - through_hole - counterbore",
