   "code": "from build123d import *\n\n# Create the base square plate\nplate = Box(70, 70, 12, align=(Align.CENTER, Align.CENTER, Align.MIN))\n\n# Create the counterbore hole as a single operation:\n# Start at the top (Z=12) with the counterbore diameter \u00d820 mm, 6 mm deep\n# Then the through-hole \u00d811 mm for the remaining 6 mm depth\n\n# Create a sketch on the top face to define the hole profile\nwith BuildSketch(Plane.XY.offset(12)) as sketch:\n    Circle(20/2)  # Counterbore outer diameter\n    Circle(11/2)  # Through-hole inner diameter\n\n# Extrude the counterbore down 6mm, then the inner circle through\nhole = Cylinder(radius=20/2, height=6, align=(Align.CENTER, Align.CENTER, Align.MAX))\nhole = hole + Cylinder(radius=11/2, height=12, align=(Align.CENTER, Align.CENTER, Align.MIN))\n\n# Subtract the hole from the plate\nresult = plate - hole",
