   "code": "from build123d import *\n\n# Parameters\nflange_diameter = 60\nflange_thickness = 6\nhub_outside_diameter = 30\noverall_length = 30\nbore_diameter = 20\n\n# Create the flange (bottom disk)\nflange = Cylinder(radius=flange_diameter/2, height=flange_thickness)\n\n# Create the hub (cylindrical extension) - should extend from z=6 to z=30\n# So height needs to be 24 mm\nhub_height = overall_length - flange_thickness\nhub = Cylinder(radius=hub_outside_diameter/2, height=hub_height)\nhub = hub.translate((0, 0, flange_thickness))\n\n# Combine flange and hub\ncombined = flange + hub\n\n# Create the bore - extends full length from z=0 to z=30\nbore = Cylinder(radius=bore_diameter/2, height=overall_length)\n\n# Subtract bore from combined solid\nresult = combined - bore",
