   "code": "from build123d import *\n\n# Create the flanged bushing\n# Flange: 60mm diameter, 6mm thick at base (Z=0 to Z=6)\nflange = Cylinder(radius=30, height=6)\n\n# Hub: 30mm diameter, 24mm tall (Z=6 to Z=30)\n# Cylinder base is at the center of the object in build123d, so translate to position the bottom at Z=6\nhub = Cylinder(radius=15, height=24)\nhub = hub.translate((0, 0, 18))  # Translate so bottom is at Z=6 (6 + 24/2 = 18)\n\n# Combine flange and hub\nbushing = flange + hub\n\n# Create the bore: 20mm diameter, 30mm tall (Z=0 to Z=30)\n# Center it at Z=15 so it spans the full 30mm\nbore = Cylinder(radius=10, height=30)\nbore = bore.translate((0, 0, 15))\n\n# Subtract the bore from the bushing\nresult = bushing - bore",
