   "code": "from build123d import *\nimport math\n\n# Create the L-bracket from two rectangular plates\n\n# Base plate: 60 mm x 40 mm x 8 mm\n# Positioned with bottom at Z=0\nbase_plate = Box(60, 40, 8, align=(Align.CENTER, Align.CENTER, Align.MIN))\n\n# Vertical wall plate: 60 mm wide x 8 mm thick x 40 mm tall\n# Rising from one 60 mm edge of the base (the Y-direction edge at Y=20)\nwall_plate = Box(60, 8, 40, align=(Align.CENTER, Align.MIN, Align.MIN))\nwall_plate = wall_plate.translate((0, 20, 0))\n\n# Combine the two plates\nbracket = base_plate + wall_plate\n\n# Hole 1: Through base plate\n# \u00d88 mm, vertical axis (Z-direction)\n# Centred 30 mm along the width (X-direction): X=0 (since width is 60mm centered)\n# 28 mm from the wall: Y = 20 - 28 = -8\nhole1 = Cylinder(radius=4, height=10, align=(Align.CENTER, Align.CENTER, Align.MIN))\nhole1 = hole1.translate((0, -8, -1))\n\n# Hole 2: Through vertical wall\n# \u00d88 mm, horizontal axis (Y-direction, perpendicular to wall face)\n# The wall is oriented with its face perpendicular to Y-axis\n# Centred 30 mm along the width (X-direction): X=0\n# 24 mm above the base bottom: Z=24\n# Cylinder initially along Z, rotate 90\u00b0 around X-axis to align with Y-axis\nhole2 = Cylinder(radius=4, height=12, align=(Align.CENTER, Align.CENTER, Align.MIN))\nhole2 = hole2.rotate(Axis.X, math.pi / 2)  # 90 degrees to align with Y-axis\nhole2 = hole2.translate((0, 20, 24))  # Position at wall inner surface (Y=20)\n\n# Subtract holes from bracket\nresult = bracket - hole1 - hole2",
