   "code": "from build123d import *\n\n# Create the L-bracket from two rectangular plates\n\n# Base plate: 60 mm x 40 mm x 8 mm\n# Positioned with one edge at origin, extending in +X and +Y\nbase_plate = Box(60, 40, 8, align=(Align.CENTER, Align.CENTER, Align.MIN))\n\n# Vertical wall plate: 60 mm wide x 8 mm thick x 40 mm tall\n# Rising from one 60 mm edge of the base (the +Y edge at Y=20)\n# The wall should be at Y=20 (the far edge of base), extending in +Z\nwall_plate = Box(60, 8, 40, align=(Align.CENTER, Align.MIN, Align.MIN))\nwall_plate = wall_plate.move(Location((0, 20, 0)))\n\n# Combine the two plates\nbracket = base_plate + wall_plate\n\n# Drill hole through base plate (vertical axis)\n# Centred 30 mm along the width (X direction) and 28 mm from the wall\n# \"28 mm from the wall\" means 28 mm from Y=20, so Y = 20 - 28 = -8\nhole_base = Cylinder(radius=4, height=20, align=(Align.CENTER, Align.CENTER, Align.CENTER))\nhole_base = hole_base.move(Location((0, -8, 4)))\nbracket = bracket - hole_base\n\n# Drill hole through vertical wall (horizontal axis)\n# Centred 30 mm along the width (X direction) and 24 mm above the base bottom\n# The wall rises from Z=0 to Z=40, hole at Z=24\nhole_wall = Cylinder(radius=4, height=80, align=(Align.CENTER, Align.CENTER, Align.CENTER))\nhole_wall = hole_wall.rotate(Axis.X, 90)\nhole_wall = hole_wall.move(Location((0, 20, 24)))\nbracket = bracket - hole_wall\n\nresult = bracket",
