   "code": "from build123d import *\n\n# Shaft collar parameters\nod = 45        # outside diameter (mm)\nbore = 25      # bore diameter (mm)\nwidth = 15     # width / axial length (mm)\n\n# Outer cylinder\nouter = Cylinder(radius=od / 2, height=width)\n\n# Bore (through hole)\ninner = Cylinder(radius=bore / 2, height=width + 1)  # +1 to ensure clean through-cut\n\n# Final collar = outer minus bore\nresult = outer - inner",
