   "code": "from build123d import *\nimport math\n\n# Parameters\nod = 120.0          # outer diameter\nbore_d = 40.0       # bore diameter\nbolt_d = 11.0       # bolt hole diameter\npcd = 95.0          # pitch circle diameter\nthickness = 14.0    # plate thickness\nnum_bolts = 6       # number of bolt holes\n\n# Build 2D profile: outer disk minus bore minus bolt holes\nprofile = Circle(radius=od / 2.0)\nprofile -= Circle(radius=bore_d / 2.0)\n\nfor i in range(num_bolts):\n    angle = math.radians(i * 360.0 / num_bolts)\n    x = (pcd / 2.0) * math.cos(angle)\n    y = (pcd / 2.0) * math.sin(angle)\n    profile -= Pos(x, y) * Circle(radius=bolt_d / 2.0)\n\n# Extrude along +Z to create the 3D flange\nresult = extrude(profile, amount=thickness)",
   "stl": "models/a397.stl",
