   "code": "from build123d import *\n\nouter_radius = 120 / 2\nbore_radius = 40 / 2\nbolt_radius = 11 / 2\npcd_radius = 95 / 2\nthickness = 14\nnum_bolts = 6\n\nwith BuildPart() as flange:\n    Cylinder(radius=outer_radius, height=thickness, align=(Align.CENTER, Align.CENTER, Align.MIN))\n    Cylinder(radius=bore_radius, height=thickness, align=(Align.CENTER, Align.CENTER, Align.MIN), mode=Mode.SUBTRACT)\n    with PolarLocations(radius=pcd_radius, count=num_bolts):\n        Cylinder(radius=bolt_radius, height=thickness, align=(Align.CENTER, Align.CENTER, Align.MIN), mode=Mode.SUBTRACT)\n\nresult = flange.part",
