   "code": "from build123d import *\n\n# Square mounting plate: 80 x 80 x 8 mm, bottom face at Z=0\nplate = Box(80, 80, 8, align=(Align.CENTER, Align.CENTER, Align.MIN))\n\n# Four \u00d89 mm through-holes in a 50 x 50 mm square pattern centred on the plate\nhole_positions = [(-25, -25), (-25, 25), (25, -25), (25, 25)]\nholes = []\nfor x, y in hole_positions:\n    # Cylinder taller than plate, centred at Z=4 to ensure clean through-cut\n    h = Pos(x, y, 4) * Cylinder(radius=4.5, height=10)\n    holes.append(h)\n\nresult = plate\nfor h in holes:\n    result -= h",
