   "code": "import build123d\nfrom build123d import BuildPart, BuildSketch, Circle, Mode\n\n# Fallback to handle different build123d versions/capitalization\nExtrudeOp = getattr(build123d, 'Extrude', getattr(build123d, 'extrude', None))\nif ExtrudeOp is None:\n    raise ImportError(\"Cannot find Extrude or extrude in build123d\")\n\nwith BuildPart() as washer:\n    with BuildSketch() as sketch:\n        Circle(radius=20)       # OD 40 mm\n        Circle(radius=10.5, mode=Mode.SUBTRACT)  # ID 21 mm\n    ExtrudeOp(amount=3)         # Thickness 3 mm\n\nresult = washer.part",
