   "code": "from build123d import *\n\n# Square plate 70x70x12, centred at origin (Z: -6 to +6, top face at Z=+6)\nplate = Box(70, 70, 12)\n\n# Through-hole \u00d811 mm, full depth (Z: -6 to +6)\nthrough_hole = Cylinder(radius=11 / 2, height=12)\n\n# Counterbore \u00d820 mm, 6 mm deep from top face (Z: 0 to +6)\ncounterbore = Cylinder(radius=20 / 2, height=6).moved(Location((0, 0, 3)))\n\nresult = plate - through_hole - counterbore",
