   "code": "from build123d import *\n\nwith BuildPart() as plate:\n    # Base square plate: 70 x 70 x 12 mm, centered at origin\n    Box(70, 70, 12)\n    \n    # Through-hole \u00d811 mm (full penetration, slightly oversized height for clean boolean)\n    with Locations((0, 0, 0)):\n        Cylinder(radius=5.5, height=14, mode=Mode.SUBTRACT)\n    \n    # Counterbore \u00d820 mm, 6 mm deep from top face\n    # Top face is at Z=+6, counterbore goes from Z=+6 down to Z=0\n    # Cylinder centered at Z=+3 with height 6 spans Z=0 to Z=+6\n    with Locations((0, 0, 3)):\n        Cylinder(radius=10, height=6, mode=Mode.SUBTRACT)\n\nresult = plate.part",
