   "code": "from build123d import *\n\n# Flange: diameter 60 mm, thickness 6 mm, base at z=0\nflange = Cylinder(radius=30, height=6, align=(Align.CENTER, Align.CENTER, Align.MIN))\n\n# Hub: outside diameter 30 mm, from z=6 to z=30 (height 24 mm)\nhub = Pos(0, 0, 6) * Cylinder(radius=15, height=24, align=(Align.CENTER, Align.CENTER, Align.MIN))\n\n# Combine flange and hub\nbody = flange + hub\n\n# Bore: diameter 20 mm, through entire part (z=0 to z=30)\nbore = Cylinder(radius=10, height=30, align=(Align.CENTER, Align.CENTER, Align.MIN))\n\n# Final part with bore subtracted\nresult = body - bore",
