   "code": "from build123d import *\n\n# Base plate: 60 mm (X) x 40 mm (Y) x 8 mm (Z)\n# Positioned so one 60-mm edge is at Y=0, base bottom at Z=0\nbase = Pos(30, 20, 4) * Box(60, 40, 8)\n\n# Vertical wall: 60 mm (X) x 8 mm thick (Y) x 40 mm tall (Z)\n# Attached at Y=0 edge, extending outward to Y=-8, full height 0-40\nwall = Pos(30, -4, 20) * Box(60, 8, 40)\n\n# Combine into L-bracket\nbracket = base + wall\n\n# Hole through base plate: diameter 8 mm, vertical (Z-axis)\n# Centred 30 mm along width (X=30) and 28 mm from wall inner face (Y=28)\nbase_hole = Pos(30, 28, 4) * Cylinder(radius=4, height=20)\n\n# Hole through vertical wall: diameter 8 mm, horizontal (Y-axis)\n# Centred 30 mm along width (X=30) and 24 mm above base bottom (Z=24)\nwall_hole = Pos(30, -4, 24) * Rot(90, 0, 0) * Cylinder(radius=4, height=20)\n\n# Subtract holes\nbracket = bracket - base_hole - wall_hole\n\nresult = bracket",
