   "code": "from build123d import *\n\n# Base plate: 60 x 40 x 8 mm, minimum corner at origin\nbase = Box(60, 40, 8, align=(Align.MIN, Align.MIN, Align.MIN))\n\n# Vertical wall: 60 wide x 8 thick x 40 tall, rising from Y=40 edge\nwall = Pos(0, 40, 0) * Box(60, 8, 40, align=(Align.MIN, Align.MIN, Align.MIN))\n\n# Combine into L-bracket\nbracket = base + wall\n\n# Hole 1: \u00d88 mm through base plate (vertical / Z-axis)\n# Centred at X=30, Y=12 (28 mm from wall inner face at Y=40)\n# Cylinder height 20 ensures clean through-cut beyond 8 mm plate\nhole1 = Pos(30, 12, 4) * Cylinder(4, 20)\n\n# Hole 2: \u00d88 mm through vertical wall (horizontal / Y-axis)\n# Centred at X=30, Y=44 (mid-wall), Z=24 (24 mm above base bottom)\n# Rot(90,0,0) rotates cylinder from Z-axis to Y-axis\nhole2 = Pos(30, 44, 24) * Rot(90, 0, 0) * Cylinder(4, 20)\n\n# Final solid with both holes\nresult = bracket - hole1 - hole2",
   "stl": "models/a412.stl",
   "ref_stl": "models/ref_T2-lbracket.stl"
