   "code": "from build123d import *\n\n# Disc: diameter 80 mm, thickness 16 mm (Z = 0 to 16)\ndisc = Cylinder(radius=40, height=16, align=(Align.CENTER, Align.CENTER, Align.MIN))\n\n# Hub: diameter 32 mm, full height 36 mm (Z = 0 to 36)\n# Union with disc gives the hub extending 20 mm above the disc\nhub = Cylinder(radius=16, height=36, align=(Align.CENTER, Align.CENTER, Align.MIN))\n\nbody = disc + hub\n\n# Bore: diameter 16 mm, through entire part\nbore = Cylinder(radius=8, height=40, align=(Align.CENTER, Align.CENTER, Align.MIN))\n\nresult = body - bore",
