   "code": "from build123d import *\n\nwith BuildPart() as part:\n    # Disc: diameter 80, thickness 16, base at Z=0\n    Cylinder(radius=40, height=16, align=(Align.CENTER, Align.CENTER, Align.MIN))\n    # Hub: diameter 32, extending from top of disc (Z=16) to Z=36\n    with Locations((0, 0, 16)):\n        Cylinder(radius=16, height=20, align=(Align.CENTER, Align.CENTER, Align.MIN))\n    # Bore: diameter 16, through entire 36 mm height\n    Cylinder(radius=8, height=36, align=(Align.CENTER, Align.CENTER, Align.MIN), mode=Mode.SUBTRACT)\n\nresult = part.part",
