   "code": "from build123d import *\nimport math\n\n# Parameters\nouter_diameter = 120  # mm\nbore_diameter = 40    # mm\nbolt_hole_diameter = 11  # mm\nbolt_circle_diameter = 95  # mm\nthickness = 14  # mm\nnum_bolts = 6\n\n# Create the main flange disc\nwith BuildPart() as flange:\n    # Main cylinder (flange body)\n    Cylinder(radius=outer_diameter / 2, height=thickness)\n    \n    # Central bore (subtract)\n    Cylinder(radius=bore_diameter / 2, height=thickness, mode=Mode.SUBTRACT)\n    \n    # Bolt holes - equally spaced on bolt circle\n    bolt_radius = bolt_circle_diameter / 2\n    for i in range(num_bolts):\n        angle = i * 360 / num_bolts\n        x = bolt_radius * math.cos(math.radians(angle))\n        y = bolt_radius * math.sin(math.radians(angle))\n        with Locations((x, y, 0)):\n            Cylinder(radius=bolt_hole_diameter / 2, height=thickness, mode=Mode.SUBTRACT)\n\nresult = flange.part",
