   "code": "from build123d import *\n\n# Create the square mounting plate\nwith BuildPart() as plate:\n    # Base plate: 80 x 80 x 8 mm\n    Box(80, 80, 8)\n    \n    # Four \u00d89 mm holes in a 50x50 mm pattern centred on plate\n    # Each hole centre is 25 mm from plate centre along both axes\n    hole_positions = [\n        (25, 25),\n        (25, -25),\n        (-25, 25),\n        (-25, -25),\n    ]\n    \n    for x, y in hole_positions:\n        with Locations((x, y, 0)):\n            Hole(radius=4.5, depth=8)\n\nresult = plate.part",
