   "code": "from build123d import *\n\n# Create the square plate\nwith BuildPart() as part:\n    # Base plate 70x70x12\n    Box(70, 70, 12)\n    \n    # Counterbore from top face (top face is at z=+6, bottom at z=-6)\n    # Through-hole: \u00d811 mm, full depth 12 mm\n    # Counterbore: \u00d820 mm, 6 mm deep from top\n    \n    # Counterbore pocket (\u00d820, 6 mm deep from top)\n    with Locations((0, 0, 6)):  # top face center\n        CounterBoreHole(\n            radius=11/2,        # through-hole radius\n            counter_bore_radius=20/2,  # counterbore radius\n            counter_bore_depth=6,      # counterbore depth\n            depth=12                   # total depth (through)\n        )\n\nresult = part.part",
