   "code": "from build123d import *\n\n# Parameters\nflange_diameter = 60\nflange_thickness = 6\nhub_diameter = 30\nbore_diameter = 20\noverall_length = 30\nhub_length = overall_length - flange_thickness  # 24 mm\n\nwith BuildPart() as bp:\n    # Base flange\n    with BuildSketch(Plane.XY):\n        Circle(flange_diameter / 2)\n    extrude(amount=flange_thickness)\n    \n    # Hub extending above flange\n    with BuildSketch(Plane.XY.offset(flange_thickness)):\n        Circle(hub_diameter / 2)\n    extrude(amount=hub_length)\n    \n    # Bore through entire part\n    with BuildSketch(Plane.XY):\n        Circle(bore_diameter / 2)\n    extrude(amount=overall_length, mode=Mode.SUBTRACT)\n\nresult = bp.part",
   "stl": "models/a447.stl",
