   "code": "from build123d import *\n\n# Parameters\nflange_radius = 30      # 60mm diameter\nflange_thickness = 6\nhub_radius = 15         # 30mm diameter\nbore_radius = 10        # 20mm diameter\noverall_length = 30\nhub_height = overall_length - flange_thickness  # 24mm\n\n# Build each solid explicitly and combine\nflange = Cylinder(radius=flange_radius, height=flange_thickness, align=(Align.CENTER, Align.CENTER, Align.MIN))\nhub = Cylinder(radius=hub_radius, height=hub_height, align=(Align.CENTER, Align.CENTER, Align.MIN))\nhub = hub.moved(Location((0, 0, flange_thickness)))\n\nbody = flange.fuse(hub)\n\nbore = Cylinder(radius=bore_radius, height=overall_length, align=(Align.CENTER, Align.CENTER, Align.MIN))\n\nresult = body.cut(bore)",
   "stl": "models/a448.stl",
