   "code": "from build123d import *\n\n# Parameters\nthickness = 8       # plate thickness\nbase_length = 60    # base plate length (X)\nbase_width = 40     # base plate width (Y)\nwall_height = 40    # overall height of vertical wall (from base bottom)\nwall_width = 60     # wall width (X) = base_length\nhole_dia = 8        # hole diameter\n\n# Build the L-bracket\nwith BuildPart() as bp:\n    # Horizontal base plate: 60 x 40 x 8 mm\n    # Positioned so its bottom face is at Z=0, spanning X: 0..60, Y: 0..40\n    with BuildSketch(Plane.XY):\n        Rectangle(base_length, base_width, align=(Align.MIN, Align.MIN))\n    extrude(amount=thickness)\n    \n    # Vertical wall: 60 x 8 x 40 mm (thickness in Y direction)\n    # Rises from one 60mm edge (Y=0 edge) of the base\n    # Wall occupies X: 0..60, Y: 0..8, Z: 0..40\n    # The base already fills Z: 0..8 in that region, so we add Z: 8..40\n    with BuildSketch(Plane.XY.offset(thickness)):\n        Rectangle(wall_width, thickness, align=(Align.MIN, Align.MIN))\n    extrude(amount=wall_height - thickness)  # from Z=8 to Z=40\n    \n    # Hole through base plate (vertical axis, along Z)\n    # Centred X=30, Y=28 (28 mm from wall at Y=0)\n    with BuildSketch(Plane(origin=(30, 28, 0), z_dir=(0, 0, 1))):\n        Circle(hole_dia / 2)\n    extrude(amount=thickness, mode=Mode.SUBTRACT)\n    \n    # Hole through vertical wall (horizontal axis, along Y)\n    # Centred X=30, Z=24 (24 mm above base bottom)\n    # Wall is at Y=0..8\n    with BuildSketch(Plane(origin=(30, 0, 24), z_dir=(0, 1, 0))):\n        Circle(hole_dia / 2)\n    extrude(amount=thickness, mode=Mode.SUBTRACT)\n\nresult = bp.part",
