   "code": "from build123d import *\nimport math\n\n# Dimensions in mm\nouter_diameter = 120.0\nbore_diameter = 40.0\nbolt_hole_diameter = 11.0\nbolt_circle_diameter = 95.0\nplate_thickness = 14.0\nbolt_count = 6\n\nouter_radius = outer_diameter / 2\nbore_radius = bore_diameter / 2\nbolt_hole_radius = bolt_hole_diameter / 2\nbolt_circle_radius = bolt_circle_diameter / 2\n\nwith BuildPart() as flange:\n    # Main circular flange plate\n    Cylinder(\n        radius=outer_radius,\n        height=plate_thickness,\n        align=(Align.CENTER, Align.CENTER, Align.CENTER),\n    )\n\n    # Central through bore\n    Cylinder(\n        radius=bore_radius,\n        height=plate_thickness + 2.0,\n        align=(Align.CENTER, Align.CENTER, Align.CENTER),\n        mode=Mode.SUBTRACT,\n    )\n\n    # Six equally spaced through bolt holes on 95 mm PCD\n    with PolarLocations(radius=bolt_circle_radius, count=bolt_count, start_angle=0):\n        Cylinder(\n            radius=bolt_hole_radius,\n            height=plate_thickness + 2.0,\n            align=(Align.CENTER, Align.CENTER, Align.CENTER),\n            mode=Mode.SUBTRACT,\n        )\n\nresult = flange.part",
   "stl": "models/a486.stl",
   "ref_stl": "models/ref_T1-flange-6bolt.stl"
