   "code": "from build123d import Cylinder\nimport math\n\n# Dimensions in millimetres\nouter_diameter = 120.0\nbore_diameter = 40.0\nbolt_hole_diameter = 11.0\nbolt_circle_diameter = 95.0\nthickness = 14.0\nhole_cut_depth = thickness + 2.0\n\n# Base flange plate\nresult = Cylinder(radius=outer_diameter / 2.0, height=thickness)\n\n# Central through bore\nresult = result - Cylinder(radius=bore_diameter / 2.0, height=hole_cut_depth)\n\n# Six equally spaced through bolt holes on 95 mm PCD\nbolt_circle_radius = bolt_circle_diameter / 2.0\nfor i in range(6):\n    angle = 2.0 * math.pi * i / 6.0\n    x = bolt_circle_radius * math.cos(angle)\n    y = bolt_circle_radius * math.sin(angle)\n    bolt_hole = Cylinder(\n        radius=bolt_hole_diameter / 2.0,\n        height=hole_cut_depth,\n    ).translate((x, y, 0))\n    result = result - bolt_hole",
