   "code": "from build123d import *\nimport math\n\n# Dimensions in mm\nouter_diameter = 120.0\nbore_diameter = 40.0\nbolt_hole_diameter = 11.0\nbolt_circle_diameter = 95.0\nthickness = 14.0\nthrough_cut_height = thickness + 2.0\n\n# Main circular flange plate\nresult = Cylinder(\n    radius=outer_diameter / 2.0,\n    height=thickness,\n    align=(Align.CENTER, Align.CENTER, Align.CENTER),\n)\n\n# Concentric through bore\nresult = result - Cylinder(\n    radius=bore_diameter / 2.0,\n    height=through_cut_height,\n    align=(Align.CENTER, Align.CENTER, Align.CENTER),\n)\n\n# Six equally spaced bolt holes on 95 mm PCD\nbolt_radius = bolt_circle_diameter / 2.0\nfor i in range(6):\n    angle = math.radians(i * 60.0)\n    x = bolt_radius * math.cos(angle)\n    y = bolt_radius * math.sin(angle)\n    bolt_hole = Pos(x, y, 0) * Cylinder(\n        radius=bolt_hole_diameter / 2.0,\n        height=through_cut_height,\n        align=(Align.CENTER, Align.CENTER, Align.CENTER),\n    )\n    result = result - bolt_hole",
