   "code": "from build123d import BuildPart, Cylinder, Mode, PolarLocations\n\n# Circular pipe flange: OD 120 mm, thickness 14 mm, bore \u00d840 mm,\n# six \u00d811 mm through bolt holes on \u00d895 mm PCD.\nwith BuildPart() as flange:\n    # Main flange plate\n    Cylinder(radius=60.0, height=14.0)\n\n    # Central through bore\n    Cylinder(radius=20.0, height=20.0, mode=Mode.SUBTRACT)\n\n    # Six equally spaced through bolt holes on 95 mm PCD\n    with PolarLocations(radius=47.5, count=6):\n        Cylinder(radius=5.5, height=20.0, mode=Mode.SUBTRACT)\n\nresult = flange.part",
