   "code": "from build123d import *\nfrom math import cos, sin, radians\n\nouter_diameter = 120.0\nthickness = 14.0\nhalf_thickness = thickness / 2.0\nbore_diameter = 40.0\nbolt_count = 6\nbolt_circle_diameter = 95.0\nbolt_circle_radius = bolt_circle_diameter / 2.0\nbolt_hole_diameter = 11.0\n\nthrough_cut_height = thickness + 2.0\n\nbolt_locations = [\n    (\n        bolt_circle_radius * cos(radians(i * 360.0 / bolt_count)),\n        bolt_circle_radius * sin(radians(i * 360.0 / bolt_count)),\n        0.0,\n    )\n    for i in range(bolt_count)\n]\n\nwith BuildPart() as flange:\n    Cylinder(\n        radius=outer_diameter / 2.0,\n        height=thickness,\n        align=(Align.CENTER, Align.CENTER, Align.CENTER),\n    )\n\n    Cylinder(\n        radius=bore_diameter / 2.0,\n        height=through_cut_height,\n        align=(Align.CENTER, Align.CENTER, Align.CENTER),\n        mode=Mode.SUBTRACT,\n    )\n\n    with Locations(*bolt_locations):\n        Cylinder(\n            radius=bolt_hole_diameter / 2.0,\n            height=through_cut_height,\n            align=(Align.CENTER, Align.CENTER, Align.CENTER),\n            mode=Mode.SUBTRACT,\n        )\n\nresult = flange.part",
