   "code": "from build123d import Box, Cylinder, Pos\n\n# Dimensions in mm\nplate_size = 70\nplate_thickness = 12\n\nthrough_hole_diameter = 11\ncounterbore_diameter = 20\ncounterbore_depth = 6\n\n# Base square plate, centered at origin: top face at Z=+6, bottom face at Z=-6\nplate = Box(plate_size, plate_size, plate_thickness)\n\n# Central through-hole, oversized height to guarantee complete cut through plate\nthrough_hole = Cylinder(radius=through_hole_diameter / 2, height=plate_thickness + 4)\n\n# Counterbore from top face, spanning Z=0 to Z=+6\ncounterbore = Pos(0, 0, plate_thickness / 2 - counterbore_depth / 2) * Cylinder(\n    radius=counterbore_diameter / 2,\n    height=counterbore_depth,\n)\n\n# Final part\nresult = plate - through_hole - counterbore",
