   "code": "from build123d import *\n\n# Units: millimetres\nPLATE_SIDE = 70.0\nPLATE_THICKNESS = 12.0\nTHROUGH_HOLE_DIAMETER = 11.0\nCOUNTERBORE_DIAMETER = 20.0\nCOUNTERBORE_DEPTH = 6.0\n\n# Small cutter overrun to ensure clean boolean cuts through/open to faces\nCUT_OVERRUN = 1.0\n\ntop_z = PLATE_THICKNESS / 2.0\ncounterbore_cut_height = COUNTERBORE_DEPTH + CUT_OVERRUN\ncounterbore_cut_center_z = top_z - COUNTERBORE_DEPTH + counterbore_cut_height / 2.0\n\nwith BuildPart() as plate_model:\n    # 70 x 70 x 12 square plate, centered on the origin\n    Box(\n        PLATE_SIDE,\n        PLATE_SIDE,\n        PLATE_THICKNESS,\n        align=(Align.CENTER, Align.CENTER, Align.CENTER),\n    )\n\n    # Central \u00d811 mm through-hole\n    Cylinder(\n        radius=THROUGH_HOLE_DIAMETER / 2.0,\n        height=PLATE_THICKNESS + 2.0 * CUT_OVERRUN,\n        align=(Align.CENTER, Align.CENTER, Align.CENTER),\n        mode=Mode.SUBTRACT,\n    )\n\n    # Central \u00d820 mm counterbore, 6 mm deep from the top face\n    with Locations((0.0, 0.0, counterbore_cut_center_z)):\n        Cylinder(\n            radius=COUNTERBORE_DIAMETER / 2.0,\n            height=counterbore_cut_height,\n            align=(Align.CENTER, Align.CENTER, Align.CENTER),\n            mode=Mode.SUBTRACT,\n        )\n\nresult = plate_model.part",
