   "code": "from build123d import Align, Cylinder\n\n# Flanged bushing dimensions in mm\nflange_diameter = 60\nflange_thickness = 6\nhub_diameter = 30\noverall_length = 30\nbore_diameter = 20\n\n# Derived dimensions\nhub_height = overall_length - flange_thickness\n\n# Base flange: \u00d860 x 6 mm, from Z=0 to Z=6\nflange = Cylinder(\n    radius=flange_diameter / 2,\n    height=flange_thickness,\n    align=(Align.CENTER, Align.CENTER, Align.MIN),\n)\n\n# Coaxial hub: \u00d830, from Z=6 to Z=30\nhub = Cylinder(\n    radius=hub_diameter / 2,\n    height=hub_height,\n    align=(Align.CENTER, Align.CENTER, Align.MIN),\n).translate((0, 0, flange_thickness))\n\n# Through bore: \u00d820, from Z=0 to Z=30\nbore = Cylinder(\n    radius=bore_diameter / 2,\n    height=overall_length,\n    align=(Align.CENTER, Align.CENTER, Align.MIN),\n)\n\n# Final flanged bushing solid\nresult = (flange + hub) - bore",
