   "code": "from build123d import *\nfrom math import cos, sin, pi\n\n# Define parameters\nouter_diameter = 120\nbore_diameter = 40\nbolt_hole_diameter = 11\nbolt_pcd = 95  # Bolt circle diameter\nnum_bolts = 6\nplate_thickness = 14\n\n# Create the main flange body\nflange = Cylinder(radius=outer_diameter/2, height=plate_thickness)\n\n# Create the central bore\nbore = Cylinder(radius=bore_diameter/2, height=plate_thickness)\nflange = flange - bore\n\n# Create bolt holes\n# Calculate radius of bolt circle\nbolt_radius = bolt_pcd / 2\n\n# Create each bolt hole\nfor i in range(num_bolts):\n    angle = (i * 360 / num_bolts)\n    # Position of bolt hole center\n    x = bolt_radius * cos(angle * pi / 180)\n    y = bolt_radius * sin(angle * pi / 180)\n    \n    # Create bolt hole cylinder\n    bolt_hole = Cylinder(\n        radius=bolt_hole_diameter/2,\n        height=plate_thickness\n    ).translate((x, y, 0))\n    \n    # Subtract from flange\n    flange = flange - bolt_hole\n\nresult = flange",
