   "code": "from build123d import *\n\n# Specifications\nouter_diameter = 120\nbore_diameter = 40\nbolt_hole_diameter = 11\nbolt_circle_diameter = 95\nnum_bolts = 6\nplate_thickness = 14\n\n# Create the base circular plate\nplate = Cylinder(radius=outer_diameter/2, height=plate_thickness)\n\n# Create the central bore\nbore = Cylinder(radius=bore_diameter/2, height=plate_thickness)\n\n# Create bolt holes\nbolt_holes = []\nbolt_hole_radius = bolt_circle_diameter / 2\n\nfor i in range(num_bolts):\n    angle = (360 / num_bolts) * i\n    hole = Cylinder(\n        radius=bolt_hole_diameter/2,\n        height=plate_thickness\n    ).moved(\n        Pos(\n            bolt_hole_radius * cos(angle * PI / 180),\n            bolt_hole_radius * sin(angle * PI / 180),\n            0\n        )\n    )\n    bolt_holes.append(hole)\n\n# Combine all holes to subtract from the plate\nall_holes = bore\nfor hole in bolt_holes:\n    all_holes = all_holes.union(hole)\n\n# Subtract all holes from the plate\nresult = plate.cut(all_holes)",
