   "code": "from build123d import *\nfrom math import cos, sin, pi\n\n# Parameters\nouter_diameter = 120\nbore_diameter = 40\nbolt_hole_diameter = 11\npcd = 95  # Pitch Circle Diameter\nnum_bolts = 6\nplate_thickness = 14\n\n# Create the base plate\nbase_plate = Cylinder(radius=outer_diameter / 2, height=plate_thickness)\n\n# Create the central bore\nbore = Cylinder(radius=bore_diameter / 2, height=plate_thickness)\n\n# Create the bolt holes\nbolt_holes = []\nfor i in range(num_bolts):\n    angle = (360 / num_bolts) * i\n    x = (pcd / 2) * cos(angle * pi / 180)\n    y = (pcd / 2) * sin(angle * pi / 180)\n    bolt_hole = Cylinder(\n        radius=bolt_hole_diameter / 2,\n        height=plate_thickness\n    ).moved(Pos(x, y, 0))\n    bolt_holes.append(bolt_hole)\n\n# Subtract bore and bolt holes from base plate\nresult = base_plate - bore\nfor bolt_hole in bolt_holes:\n    result = result - bolt_hole",
