   "code": "from build123d import *\n\n# Create a flanged bushing\n# - Flange: diameter 60 mm, thickness 6 mm\n# - Hub: outside diameter 30 mm, extending above flange\n# - Overall length: 30 mm\n# - Bore: \u00d820 mm through entire part\n\n# Start with the flange (base)\nflange = Cylinder(radius=30, height=6)\n\n# Create the hub on top of the flange\n# Hub outer diameter is 30 mm (radius 15 mm)\n# Overall length is 30 mm, flange is 6 mm, so hub height is 24 mm\nhub_height = 30 - 6\nhub = Cylinder(radius=15, height=hub_height)\nhub = hub.translate((0, 0, 6))\n\n# Combine flange and hub\nbushing = flange + hub\n\n# Create the bore (\u00d820 mm, passes through entire part)\n# Bore radius is 10 mm, height must be at least 30 mm to go through everything\nbore = Cylinder(radius=10, height=30)\n\n# Cut the bore from the bushing\nresult = bushing - bore",
